window.FS_DATA=window.FS_DATA||{};FS_DATA["maksim-dashuria"]={"title":"Kapituj mbi dashurinë","author":"Shën Maksim Pohuesi","sections":[{"title":"Përmbajtja","items":[{"title":"Parathënie drejtuar atë Elpidit","blocks":[{"t":"p","x":"Ja, o atë Elpid, bashkë me fjalën për jetën asketike po i dërgoj shenjtërisë sate edhe fjalën për dashurinë, në katër qindëshe kapitujsh, aq sa janë edhe Ungjijtë. Ndoshta në të s’ka asgjë të denjë për atë që pret prej meje, por të kam dhënë aq sa munda. Le ta dijë, megjithatë, shenjtëria jote se as këto nuk janë fryt i punës së mendjes sime. Kam përshkuar shkrimet e Etërve të shenjtë, kam mbledhur prej tyre mendimet që i përkasin kësaj teme dhe kam ngjeshur shumë gjëra në pak fjalë, duke i ndarë në kapituj që të mund të rroken me një vështrim e të mbahen lehtë mend. Po t’i dërgoj, pra, duke të lutur t’i lexosh me mirëdashje e të kërkosh në to vetëm atë që të bën dobi. Kaloje pa u ndalur mungesën e hijeshisë së fjalëve dhe lutu për mua të përulurin, që jam i zhveshur nga çdo dobi shpirtërore."},{"t":"p","x":"Edhe për këtë të lutem, që të mos i quash fjalët e mia një bezdi. Kam përmbushur një porosi. Këtë e them sepse sot jemi shumë ne që i lodhim të tjerët me fjalë, kurse tejet të paktë janë ata që mësojnë të tjerët ose mësojnë vetë me vepra. Përkushtoji, pra, mund e vëmendje secilit kapitull. Se, ma do mendja, jo gjithçka kuptohet lehtë nga të gjithë. Përkundrazi, shumicës së lexuesve u duhet t’i shqyrtojnë me shumë kujdes shumicën e këtyre fjalëve, edhe kur ato duken të thëna fare thjesht. Ndoshta, duke i zbërthyer, do të dalë në dritë diçka e dobishme për shpirtin. Dhe me hirin e Perëndisë kjo ka për t’iu zbuluar me siguri atij që lexon me mendje të çiltër, me frikë Perëndie dhe me dashuri. Por atij që lexon këtë shkrim a cilindo tjetër për të gjuajtur fjalë me të cilat të qortojë autorin, që në mendjemadhësinë e vet të duket gjoja më i urtë se ai, dhe që nuk kërkon ndonjë dobi shpirtërore, kurrë, nga asnjë anë, nuk ka për t’iu zbuluar asgjë e dobishme."}]}]},{"title":"Qindëshja e parë","items":[{"title":"Kreu 1","blocks":[{"t":"p","x":"Dashuria është një prirje e mirë e shpirtit, në saje të së cilës ai nuk çmon asgjë që ekziston më shumë se njohjen e Perëndisë. Është e pamundur që kjo dashuri të zërë rrënjë tek ai që është i lidhur me pasion pas ndonjë gjëje tokësore."}]},{"title":"Kreu 2","blocks":[{"t":"p","x":"Dashurinë e lind papasionshmëria. Papasionshmërinë e lind shpresa te Perëndia, shpresën e lindin qëndresa dhe zemërgjerësia në durim, këto i lind vetëpërmbajtja që shtrihet mbi gjithçka, vetëpërmbajtjen e lind frika e Perëndisë, kurse frikën e lind besimi te Zoti."}]},{"title":"Kreu 3","blocks":[{"t":"p","x":"Kush i beson Zotit, i druhet dënimit. Kush i druhet dënimit, përmbahet prej pasioneve. Kush përmbahet prej pasioneve, i duron mundimet. Kush i duron mundimet, do të ketë shpresën te Perëndia. Shpresa te Perëndia e shkëput njeriun nga çdo lidhje e pasionuar me tokën. Kur mendja çlirohet nga një lidhje e tillë, fiton dashurinë për Perëndinë."}]},{"title":"Kreu 4","blocks":[{"t":"p","x":"Kush e do Perëndinë, çmon njohjen e Tij më shumë se gjithçka të bërë prej Tij dhe, i shtyrë nga malli, i përkushtohet asaj pa pushim."}]},{"title":"Kreu 5","blocks":[{"t":"p","x":"Në qoftë se gjithçka që ekziston është bërë me anë të Perëndisë dhe për Perëndinë, e në qoftë se Perëndia qëndron më lart se gjithçka e bërë me anë të Tij, atëherë kush lë më të lartën dhe jepet pas gjërave më të ulëta tregon se çmon më shumë se Perëndinë ato që janë bërë me anë të Tij."}]},{"title":"Kreu 6","blocks":[{"t":"p","x":"Ai që e ka mendjen të mbërthyer pas dashurisë për Perëndinë nuk mbahet pas asgjëje të dukshme, madje as pas trupit të vet, të cilin e sheh si të ishte i një tjetri."}]},{"title":"Kreu 7","blocks":[{"t":"p","x":"Në qoftë se shpirti qëndron më lart se trupi dhe Perëndia që krijoi botën qëndron pakrahasimisht më lart se bota, atëherë ai që çmon trupin më shumë se shpirtin dhe botën e krijuar më shumë se Perëndinë që e krijoi, nuk ndryshon në asgjë nga idhujtarët."}]},{"title":"Kreu 8","blocks":[{"t":"p","x":"Kush e largon mendjen nga dashuria për Perëndinë e nga të qëndruarit pranë Tij dhe e mban të lidhur pas ndonjë gjëje që kapin shqisat, është pikërisht ai që çmon trupin më shumë se shpirtin dhe gjërat e krijuara më shumë se Perëndinë që i krijoi."}]},{"title":"Kreu 9","blocks":[{"t":"p","x":"Nëse jeta e mendjes është ndriçimi që vjen prej njohjes dhe këtë ndriçim e lind dashuria për Perëndinë, me të drejtë është thënë se asgjë nuk është më e madhe se dashuria hyjnore."}]},{"title":"Kreu 10","blocks":[{"t":"p","x":"Kur vrulli i dashurisë e nxjerr mendjen jashtë vetes e drejt Perëndisë, ajo nuk ndien më as veten, as ndonjë gjë tjetër që ekziston. E përndritur nga drita hyjnore dhe e pafund, ajo nuk ndien më asgjë nga ato që ka bërë Perëndia, ashtu si syri trupor nuk i dallon më yjet kur lind dielli."}]},{"title":"Kreu 11","blocks":[{"t":"p","x":"Të gjitha virtytet e ndihmojnë mendjen të arrijë te dashuria e zjarrtë për Perëndinë, por më shumë se të gjitha, lutja e pastër. Sepse prej saj mendja merr krahë drejt Perëndisë dhe del përtej gjithçkaje që ekziston."}]},{"title":"Kreu 12","blocks":[{"t":"p","x":"Kur, përmes dashurisë, mendja rrëmbehet prej njohjes hyjnore, del përtej gjithçkaje që ekziston dhe ndien pafundësinë e Perëndisë, atëherë, siç i ndodhi Isaisë hyjnor, mahnitja e bën të ndërgjegjshme për vogëlsinë e vet. Dhe ajo thotë nga thellësia e zemrës fjalët e profetit: «Mjerë unë, se u dërrmova! Sepse jam njeri me buzë të papastra dhe banoj mes një populli me buzë të papastra, e megjithatë sytë e mi panë Mbretin, Zotin Savaoth!»"}]},{"title":"Kreu 13","blocks":[{"t":"p","x":"Ai që e do Perëndinë nuk mund të mos e dojë edhe çdo njeri si veten, sado që i rëndojnë pasionet e atyre që ende nuk janë pastruar. Prandaj, kur sheh se po kthehen në udhën e drejtë dhe po ndreqen, gëzohet me një gëzim të pamasë e të patregueshëm."}]},{"title":"Kreu 14","blocks":[{"t":"p","x":"I papastër është shpirti i pushtuar prej pasioneve, i mbushur me mendime lakmie e urrejtjeje."}]},{"title":"Kreu 15","blocks":[{"t":"p","x":"Kush sheh në zemrën e vet qoftë edhe një gjurmë urrejtjeje për ndonjë njeri, cilido qoftë ai dhe për çfarëdo faji qoftë, është krejt i huaj për dashurinë ndaj Perëndisë. Sepse dashuria për Perëndinë nuk e duron kurrsesi urrejtjen për njeriun."}]},{"title":"Kreu 16","blocks":[{"t":"p","x":"«Kush më do», thotë Zoti, «do t’i ruajë urdhërimet e mia». Dhe: «Ky është urdhërimi im, ta doni njëri-tjetrin». Ai, pra, që nuk e do të afërmin nuk e ruan urdhërimin. E kush nuk e ruan urdhërimin, as Zotin nuk mund ta dojë."}]},{"title":"Kreu 17","blocks":[{"t":"p","x":"Lum ai njeri që ka arritur ta dojë çdo njeri njëlloj!"}]},{"title":"Kreu 18","blocks":[{"t":"p","x":"Lum ai njeri që nuk është i lidhur pas asnjë gjëje të prishshme a të përkohshme!"}]},{"title":"Kreu 19","blocks":[{"t":"p","x":"Lum ajo mendje që ka kaluar përtej gjithçkaje që ekziston dhe shijon pa pushim bukurinë hyjnore!"}]},{"title":"Kreu 20","blocks":[{"t":"p","x":"Kush kujdeset për mishin që t’i përmbushë dëshirat dhe i mban mëri të afërmit për gjëra që kalojnë, i shërben krijesës më shumë se Krijuesit."}]},{"title":"Kreu 21","blocks":[{"t":"p","x":"Kush e mban trupin larg kënaqësive dhe të lirë nga sëmundja, e ka atë bashkëshërbëtor në shërbesën e gjërave më të larta."}]},{"title":"Kreu 22","blocks":[{"t":"p","x":"Kush u ikën të gjitha dëshirave të botës, ngrihet mbi çdo trishtim të botës."}]},{"title":"Kreu 23","blocks":[{"t":"p","x":"Kush e do Perëndinë, patjetër e do edhe të afërmin. Një njeri i tillë nuk mund ta mbajë paranë për vete. E mbarështon siç i ka hije Perëndisë, duke i dhënë secilit që ka nevojë."}]},{"title":"Kreu 24","blocks":[{"t":"p","x":"Kush jep lëmoshë duke marrë për shembull Perëndinë, kur është fjala për nevojat e trupit nuk bën dallim midis të ligut e të mirit, midis të drejtit e të padrejtit. Ua ndan të gjithëve njëlloj, sipas nevojës së secilit, edhe pse, për shkak të zgjedhjes së tij të mirë, e çmon të virtytshmin më shumë se të ligun."}]},{"title":"Kreu 25","blocks":[{"t":"p","x":"Perëndia, i mirë nga natyra dhe i lirë nga çdo pasion, i do të gjithë njëlloj, si vepra të duarve të Tij. Por të virtytshmin, që edhe me vullnetin e vet bëhet i afërt me Të, e përlëvdon, ndërsa të ligun, në mirësinë e Tij, e mëshiron dhe, duke e ndrequr në këtë jetë, e kthen në udhën e drejtë. Kështu edhe njeriu që, me vullnetin e vet, është i mirë dhe i lirë nga pasionet, i do të gjithë njerëzit njëlloj. Të virtytshmin e do edhe për natyrën që kanë të përbashkët, edhe për zgjedhjen e tij të mirë. Të ligun e do për atë natyrë dhe nga dhembshuria, duke e mëshiruar si njeri të pamend që ecën në errësirë."}]},{"title":"Kreu 26","blocks":[{"t":"p","x":"Dashuria që ka njeriu në shpirt nuk njihet vetëm kur ndan me të tjerët të hollat e veta. Njihet shumë më tepër kur u jep fjalën e Perëndisë dhe u shërben me duart e veta."}]},{"title":"Kreu 27","blocks":[{"t":"p","x":"Kush ka hequr dorë me të vërtetë nga gjërat e botës dhe i shërben pa shtirje të afërmit me dashuri, çlirohet shpejt nga çdo pasion dhe bëhet pjesëtar i dashurisë dhe i njohjes hyjnore."}]},{"title":"Kreu 28","blocks":[{"t":"p","x":"Kush ka fituar brenda vetes dashurinë hyjnore nuk lodhet duke ndjekur pas Zotin, Perëndinë e vet, siç thotë Jeremia hyjnor. Çdo mundim, përqeshje dhe fyerje e përballon me trimëri, pa i vënë në llogari askujt asnjë të keqe."}]},{"title":"Kreu 29","blocks":[{"t":"p","x":"Kur dikush të fyen a të përbuz për ndonjë gjë, ruhu nga mendimet e zemërimit, se mos, me anë të hidhërimit, të ndajnë nga dashuria e të vendosin në vendin e urrejtjes."}]},{"title":"Kreu 30","blocks":[{"t":"p","x":"Kur të dhemb fort një fyerje a një çnderim, dije se ke marrë një të mirë të madhe. Me anë të atij çnderimi, përkujdesja hyjnore e ka dëbuar prej teje lavdidashjen e kotë."}]},{"title":"Kreu 31","blocks":[{"t":"p","x":"Siç nuk e ngroh trupin kujtimi i zjarrit, ashtu as besimi pa dashuri nuk ia jep shpirtit ndriçimin e njohjes."}]},{"title":"Kreu 32","blocks":[{"t":"p","x":"Sikurse drita e diellit e tërheq drejt vetes syrin e shëndoshë, ashtu edhe njohja e Perëndisë e tërheq natyrshëm drejt vetes, nëpërmjet dashurisë, mendjen e pastër."}]},{"title":"Kreu 33","blocks":[{"t":"p","x":"Mendje e pastër është ajo që është çliruar nga padija e që ndriçohet nga drita hyjnore."}]},{"title":"Kreu 34","blocks":[{"t":"p","x":"Shpirt i pastër është ai që është çliruar nga pasionet e që gazmohet pa pushim prej dashurisë hyjnore."}]},{"title":"Kreu 35","blocks":[{"t":"p","x":"Pasion i qortueshëm është një lëvizje e shpirtit kundër natyrës."}]},{"title":"Kreu 36","blocks":[{"t":"p","x":"Papasionshmëria është një gjendje paqësore e shpirtit, në të cilën ai mezi shtyhet drejt së keqes."}]},{"title":"Kreu 37","blocks":[{"t":"p","x":"Kush me zell ka fituar frytet e dashurisë nuk heq dorë prej saj, edhe sikur të pësojë të këqija pa numër. Le të të bindin për këtë Stefani, nxënësi i Krishtit, dhe ata që i ngjasojnë, si edhe vetë Krishti, që lutej për vrasësit e Tij dhe i kërkonte Atit t’i falte, sepse nuk dinin ç’bënin."}]},{"title":"Kreu 38","blocks":[{"t":"p","x":"Nëse dashurisë i përket të durojë gjatë e të sillet me mirësi, atëherë ai që grindet i zemëruar dhe vepron me ligësi bëhet, siç duket qartë, i huaj për dashurinë. E kush është i huaj për dashurinë, është i huaj për Perëndinë, meqë Perëndia është dashuri."}]},{"title":"Kreu 39","blocks":[{"t":"p","x":"«Mos thoni», thotë Jeremia hyjnor, «se ky është tempulli i Zotit». Edhe ti mos thuaj: «Vetëm besimi te Zoti Jisu Krisht mund të më shpëtojë». Kjo është e pamundur nëse, me anë të veprave, nuk fiton edhe dashurinë për Të. Sepse, po të jetë puna thjesht për të besuar, edhe demonët besojnë e dridhen."}]},{"title":"Kreu 40","blocks":[{"t":"p","x":"Vepër e dashurisë është t’i bësh mirë të afërmit me gjithë zemër, të tregosh zemërgjerësi e durim dhe çdo gjë ta përdorësh me gjykim të drejtë."}]},{"title":"Kreu 41","blocks":[{"t":"p","x":"Kush e do Perëndinë as nuk hidhëron njeri, as nuk hidhërohet me njeri për gjëra të përkohshme. Vetëm një hidhërim u shkakton të tjerëve e përjeton edhe vetë, atë që sjell shpëtim, atë me të cilin u hidhërua i lumi Pavël dhe me të cilin i hidhëroi edhe korinthianët."}]},{"title":"Kreu 42","blocks":[{"t":"p","x":"Kush e do Perëndinë, jeton që këtu mbi dhé një jetë engjëllore. Agjëron, mban agripni, psal, lutet dhe mendon përherë mirë për çdo njeri."}]},{"title":"Kreu 43","blocks":[{"t":"p","x":"Njeriu përpiqet të arrijë atë që dëshiron. E nëse Perëndia është pakrahasimisht më i mirë e më i dëshirueshëm se të gjitha të mirat e se gjithçka që mund të dëshirohet, sa zell na duhet të tregojmë vallë për të arritur tek Ai, i cili është i mirë dhe i dëshirueshëm prej natyre!"}]},{"title":"Kreu 44","blocks":[{"t":"p","x":"Mos e ndot mishin tënd me vepra të turpshme dhe mos e njollos shpirtin tënd me mendime të liga. Atëherë paqja e Perëndisë do të vijë mbi ty, duke sjellë me vete dashurinë."}]},{"title":"Kreu 45","blocks":[{"t":"p","x":"Mundoje mishin tënd me agjërim e me agripni dhe kushtoju pa u lodhur psalmodisë e lutjes. Atëherë shenjtërimi që vjen prej dëlirësisë do të zbresë mbi ty, duke sjellë me vete dashurinë."}]},{"title":"Kreu 46","blocks":[{"t":"p","x":"Atë që u bë i denjë për njohjen hyjnore dhe që, nëpërmjet dashurisë, mori ndriçimin e saj, fryma e lavdidashjes së kotë nuk do ta lëkundë kurrë. Por atë që ende nuk u bë i denjë për të, kjo frymë e hedh lehtë andej-këtej. Në qoftë se, pra, ai e mban shikimin te Perëndia në gjithçka që bën, duke i bërë të gjitha për hir të Tij, me ndihmën e Perëndisë do t’i shpëtojë lehtë asaj."}]},{"title":"Kreu 47","blocks":[{"t":"p","x":"Kush nuk e ka marrë ende njohjen hyjnore që vepron nëpërmjet dashurisë, mbahet me të madh për ato që bën sipas Perëndisë. Por kush u bë i denjë ta marrë, përsërit me gjithë shpirt fjalët e patriarkut Abraham, të thëna kur iu dha hiri të shihte shfaqjen e Perëndisë: «Unë jam dhé dhe hi»."}]},{"title":"Kreu 48","blocks":[{"t":"p","x":"Kush i druhet Zotit ka përherë pranë përulësinë si bashkëbiseduese. Mendimet që ajo i ngjall e çojnë drejt dashurisë për Perëndinë dhe drejt falënderimit. I kujtohet si jetonte dikur në botë, i kujtohen fajet e shumta e të larmishme, tundimet që i ranë mbi krye që nga rinia, dhe si e shpëtoi Zoti nga të gjitha ato e si e kaloi nga një jetë nën pushtetin e pasioneve në një jetë sipas Perëndisë. Kështu, krahas frikës, merr edhe dashurinë dhe, me shumë përulësi, i jep falënderim të pareshtur Mirëbërësit e Drejtuesit të jetës sonë."}]},{"title":"Kreu 49","blocks":[{"t":"p","x":"Mos e ndot mendjen duke duruar në të mendime të dëshirës së çrregullt e të zemërimit, se mos largohesh nga lutja e pastër dhe bie në duart e frymës së plogështisë shpirtërore."}]},{"title":"Kreu 50","blocks":[{"t":"p","x":"Mendja e humbet guximin për të qëndruar para Perëndisë pikërisht atëherë kur zë të kuvendojë me mendime të liga ose të papastra."}]},{"title":"Kreu 51","blocks":[{"t":"p","x":"I pamendi, i tërhequr andej-këtej nga pasionet, kur zemërimi ia trazon shpirtin, nxiton pa mend t’u ikë vëllezërve. Pastaj, kur ndizet nga dëshira, ndërron mendje dhe vrapon përsëri t’i takojë. I urti, në të dyja rastet, vepron përkundrazi. Kur zemërohet, pret rrënjët e trazimit dhe çlirohet nga hidhërimi që ushqen ndaj vëllezërve. Kur ndizet nga dëshira, i vë fre hovjes së paarsyeshme dhe përmbahet nga takimi që ajo i dikton."}]},{"title":"Kreu 52","blocks":[{"t":"p","x":"Në kohën e tundimeve mos e braktis manastirin tënd. Përballoji trimërisht dallgët e mendimeve, sidomos ato të trishtimit e të plogështisë shpirtërore. Sepse kështu, pasi të sprovohesh nëpër mundime sipas përkujdesjes së Perëndisë, do të kesh një shpresë të patundur tek Ai. Po ta braktisësh, do të dalësh i paprovuar, frikacak dhe i paqëndrueshëm."}]},{"title":"Kreu 53","blocks":[{"t":"p","x":"Nëse dëshiron të mos biesh nga dashuria që është sipas Perëndisë, as mos e lër vëllanë tënd të flejë i hidhëruar me ty, as ti mos fli i hidhëruar me të. Shko, pajtohu me vëllanë tënd dhe pastaj eja, e me ndërgjegje të pastër, me lutje të zjarrtë, blatoja Krishtit dhuratën e dashurisë."}]},{"title":"Kreu 54","blocks":[{"t":"p","x":"Nëse ai që i ka të gjitha dhuratat e Shpirtit, por nuk ka dashuri, nuk përfiton asgjë, sikurse thotë Apostulli hyjnor, atëherë duhet të tregojmë gjithë zellin tonë për ta fituar dashurinë."}]},{"title":"Kreu 55","blocks":[{"t":"p","x":"Nëse dashuria nuk i bën keq të afërmit, atëherë ai që e ka zili vëllanë, që hidhërohet kur vëllait i del emri për mirë, që ia njollos emrin me tallje ose, me çfarëdo ligësie, i ngre kurth, si të mos e bëjë veten të huaj për dashurinë e fajtor përpara gjykimit të përjetshëm?"}]},{"title":"Kreu 56","blocks":[{"t":"p","x":"Nëse dashuria është përmbushja e ligjit, atëherë ai që i mban mëri vëllait, që thur dredhi kundër tij, i uron të keqen e gëzohet për rënien e tij, si të mos jetë shkelës i ligjit e i denjë për dënimin e përjetshëm?"}]},{"title":"Kreu 57","blocks":[{"t":"p","x":"Nëse ai që përgojon dhe gjykon vëllanë përgojon dhe gjykon ligjin, e nëse ligji i Krishtit është dashuria, si të mos bjerë përgojuesi nga dashuria e Krishtit dhe të mos bëhet ai vetë shkaku i dënimit të tij të përjetshëm?"}]},{"title":"Kreu 58","blocks":[{"t":"p","x":"Mos ia fal veshin gjuhës së përgojuesit, as gjuhën tënde veshit të atij që ka qejf të gjejë të meta. Mos fol e mos dëgjo me ëndje fjalë kundër të afërmit, se mos biesh nga dashuria hyjnore dhe gjendesh i huaj për jetën e përjetshme."}]},{"title":"Kreu 59","blocks":[{"t":"p","x":"Mos prano të shahet ati yt dhe mos i jep zemër atij që e çnderon, se mos zemërohet Zoti për veprat e tua e të shfaros nga dheu i të gjallëve."}]},{"title":"Kreu 60","blocks":[{"t":"p","x":"Vëri fre gojës së atij që përgojon në praninë tënde, që të mos biesh bashkë me të në mëkat të dyfishtë, edhe duke e mësuar veten me një pasion shkatërrimtar, edhe duke mos e ndalur atë që flet gjepura kundër të afërmit."}]},{"title":"Kreu 61","blocks":[{"t":"p","x":"«Por unë po ju them», thotë Zoti, «duajini armiqtë tuaj, bëjuni mirë atyre që ju urrejnë, lutuni për ata që ju keqtrajtojnë». Përse i urdhëroi këto? Që të të çlirojë nga urrejtja, hidhërimi, zemërimi e mëria dhe të të bëjë të denjë për pasurinë më të madhe, për dashurinë e përsosur. Është e pamundur ta ketë këtë dashuri ai që nuk i do njëlloj të gjithë njerëzit, duke imituar Perëndinë, i cili i do të gjithë njëlloj dhe do që të gjithë të shpëtojnë e të vijnë në njohjen e së vërtetës."}]},{"title":"Kreu 62","blocks":[{"t":"p","x":"«Por unë po ju them të mos i bëni qëndresë të ligut. Kush të qëllon në faqen e djathtë, ktheja edhe tjetrën. Atij që do të të hedhë në gjyq që të të marrë këmishën, lërja edhe rrobën e sipërme. Dhe atij që të shtrëngon të bësh një milje, shko me të dy». Përse? Që ty të të ruajë nga zemërimi e nga hidhërimi, që tjetrin ta mësojë nëpërmjet durimit me të cilin ti e përballon të keqen dhe që, si i mirë që është, t’ju vërë të dyve nën zgjedhën e dashurisë."}]},{"title":"Kreu 63","blocks":[{"t":"p","x":"Për gjërat me të cilat dikur jemi lidhur me pasion, mbajmë brenda vetes edhe përfytyrime të ngarkuara me pasion. Kush i mposht këto përfytyrime, me siguri arrin të mos ua vërë veshin as vetë gjërave që ato sjellin ndër mend. Sepse lufta kundër kujtimeve është aq më e rëndë se lufta kundër vetë gjërave, sa më e lehtë është të mëkatosh në mendje sesa me vepra."}]},{"title":"Kreu 64","blocks":[{"t":"p","x":"Disa pasione janë trupore, disa shpirtërore. Truporet e marrin shkas nga trupi, shpirtëroret nga gjërat e jashtme. Të dyja palëve ua presin hovin dashuria dhe vetëpërmbajtja. Dashuria ua pret hovin pasioneve shpirtërore, vetëpërmbajtja atyre trupore."}]},{"title":"Kreu 65","blocks":[{"t":"p","x":"Disa pasione i përkasin fuqisë zemëruese të shpirtit, disa fuqisë dëshiruese të tij. Të dyja llojet vihen në lëvizje nëpërmjet shqisave, por vihen në lëvizje kur shpirti gjendet pa dashuri e pa vetëpërmbajtje."}]},{"title":"Kreu 66","blocks":[{"t":"p","x":"Pasionet e fuqisë zemëruese të shpirtit mposhten më me vështirësi se ato të fuqisë dëshiruese. Prandaj Zoti na dha, kundër tyre, ilaçin më të fuqishëm, urdhërimin e dashurisë."}]},{"title":"Kreu 67","blocks":[{"t":"p","x":"Të gjitha pasionet e tjera prekin vetëm njërën nga fuqitë e shpirtit, ose atë zemëruese, ose atë dëshiruese, ose edhe atë arsyetuese, siç ndodh me harresën dhe padijen. Kurse plogështia shpirtërore, duke shtënë në dorë të gjitha fuqitë e shpirtit, i vë në lëvizje pothuajse të gjitha pasionet njëherësh. Prandaj është më e rënda ndër të gjitha. Me të drejtë, pra, kur na dha ilaçin kundër saj, Zoti tha: «Me durimin tuaj fitojini shpirtrat tuaj»."}]},{"title":"Kreu 68","blocks":[{"t":"p","x":"Mos godit kurrë ndonjërin prej vëllezërve, sidomos pa arsye. Se mos ai, duke mos e duruar dot dhembjen, largohet, e ti nuk i shpëton më kurrë qortimit të ndërgjegjes, e cila përherë do të të sjellë hidhërim në orën e lutjes dhe do t’ia largojë mendjes sate guximin për të dalë para Perëndisë."}]},{"title":"Kreu 69","blocks":[{"t":"p","x":"Mos u bëj vend as dyshimeve, as njerëzve që të japin shkas të pengohesh për faj të dikujt. Sepse ata që gjejnë shkas për pengesë në gjithçka ndodh, me dashje a pa dashje, nuk e njohin udhën e paqes, atë udhë që, nëpërmjet dashurisë, i çon te njohja e Perëndisë ata që e duan."}]},{"title":"Kreu 70","blocks":[{"t":"p","x":"Nuk e ka ende dashurinë e përsosur kush i ndërron ndjenjat sipas qëndrimit të njerëzve, duke dashur njërin e duke urryer tjetrin për këtë a për atë arsye, ose edhe duke e dashur herë e duke e urryer herë të njëjtin njeri për po ato arsye."}]},{"title":"Kreu 71","blocks":[{"t":"p","x":"Dashuria e përsosur nuk e copëton natyrën e vetme njerëzore sipas vullneteve të ndryshme të njerëzve. Ajo e mban vështrimin vazhdimisht te kjo natyrë e përbashkët dhe i do të gjithë njerëzit njëlloj. Të virtytshmit i do si miq, kurse të ligjtë i do edhe kur i ka armiq, duke u bërë mirë, duke treguar zemërgjerësi ndaj tyre, duke duruar ç’i vjen prej tyre dhe pa ua mbajtur mend aspak të keqen. Madje, po ta kërkojë rasti, vuan edhe për ta, që, po të jetë e mundur, t’i bëjë edhe ata miq. E nëse kjo nuk bëhet, ajo prapë i qëndron besnike prirjes së vet dhe ua jep përherë njëlloj frytet e dashurisë të gjithë njerëzve. Prandaj edhe Zoti dhe Perëndia ynë Jisu Krisht, duke na treguar dashurinë e Tij, pësoi për mbarë njerëzimin dhe ua fali të gjithëve njëlloj shpresën e ngjalljes, ndonëse secili e bën vetveten të denjë ose për lavdi, ose për dënim."}]},{"title":"Kreu 72","blocks":[{"t":"p","x":"Kush ende s’është ngritur përmbi lavdinë e çnderimin, pasurinë e varfërinë, kënaqësinë e hidhërimin, nuk e ka fituar dashurinë e përsosur. Sepse dashuria e përsosur ngrihet përmbi të gjitha këto, madje përmbi vetë jetën e përkohshme dhe përmbi vdekjen."}]},{"title":"Kreu 73","blocks":[{"t":"p","x":"Dëgjo ç’thonë ata që u bënë të denjë për dashurinë e përsosur: «Kush do të na ndajë nga dashuria e Krishtit? Shtrëngimi, ngushtica, përndjekja, uria, lakuriqësia, rreziku apo shpata? Siç është shkruar: Për shkakun tënd po na vrasin gjithë ditën, na kanë parë si dele për therje. Por në të gjitha këto ne korrim fitore të plotë me anë të Atij që na deshi. Sepse jam i bindur se as vdekja, as jeta, as engjëjt, as kryesitë, as fuqitë, as të tashmet, as të ardhmet, as lartësia, as thellësia, as ndonjë krijesë tjetër nuk do të mund të na ndajë nga dashuria e Perëndisë që është në Krishtin Jisu, Zotin tonë». Kështu flasin dhe kështu veprojnë të gjithë shenjtorët kur është fjala për dashurinë ndaj Perëndisë."}]},{"title":"Kreu 74","blocks":[{"t":"p","x":"Dëgjo përsëri ç’thonë për dashurinë ndaj të afërmit: «Të vërtetën them në Krishtin, nuk gënjej, dhe dëshmon bashkë me mua ndërgjegjja ime në Shpirtin e Shenjtë se kam një hidhërim të madh dhe një dhembje të pandërprerë në zemër. Sepse do të lutesha që unë vetë të isha anatemë, i ndarë nga Krishti, për hir të vëllezërve të mi, të farefisit tim sipas mishit, të cilët janë izraelitë», e kështu me radhë. Po kështu edhe Moisiu e shenjtorët e tjerë."}]},{"title":"Kreu 75","blocks":[{"t":"p","x":"Kush ende s’është ngritur përmbi lavdinë e kënaqësinë dhe përmbi dashurinë për paranë, e cila i ushqen të dyja dhe rron për hir të tyre, nuk mund t’i presë shkaqet e zemërimit. Dhe kush nuk i pret ato, nuk mund të arrijë te dashuria e përsosur."}]},{"title":"Kreu 76","blocks":[{"t":"p","x":"Përulësia dhe durimi i mundimeve e çlirojnë njeriun nga çdo mëkat. Përulësia u pret hovin pasioneve të shpirtit, ndërsa mundimet atyre të trupit. Kështu vepron edhe i lumi David, siç duket nga fjalët me të cilat i lutet Perëndisë: «Shihe përuljen time dhe mundin tim, dhe falmi të gjitha mëkatet»."}]},{"title":"Kreu 77","blocks":[{"t":"p","x":"Me anë të urdhërimeve, Zoti i çliron nga pasionet ata që i vënë në jetë, ndërsa me anë të dogmave hyjnore u fal ndriçimin e njohjes."}]},{"title":"Kreu 78","blocks":[{"t":"p","x":"Të gjitha dogmat flasin ose për Perëndinë, ose për gjërat e dukshme dhe të padukshme, ose për përkujdesjen dhe gjykimin e Tij mbi to."}]},{"title":"Kreu 79","blocks":[{"t":"p","x":"Lëmosha e shëron fuqinë zemëruese të shpirtit. Agjërimi e fishk dëshirën e çrregullt. Lutja e pastron mendjen dhe e përgatit për soditjen e qenieve. Sepse Zoti na i ka falur urdhërimet në përputhje me fuqitë e shpirtit."}]},{"title":"Kreu 80","blocks":[{"t":"p","x":"«Mësoni prej meje», thotë Ai, «se jam i butë dhe i përulur në zemër», e kështu me radhë. Butësia e mban të patrazuar fuqinë zemëruese, kurse përulësia e çliron mendjen nga fodullëku e lavdidashja e kotë."}]},{"title":"Kreu 81","blocks":[{"t":"p","x":"Frika e Perëndisë është dy llojesh. Njëra lind brenda nesh kur dëgjojmë paralajmërimet për dënimin. Nëpërmjet saj lindin te ne me radhë vetëpërmbajtja, durimi, shpresa te Perëndia dhe papasionshmëria, prej së cilës lind dashuria. Tjetra është e bashkuar me vetë dashurinë. Ajo ngjall vazhdimisht nderim të thellë në shpirt, që afërsia e guximshme që i fal dashuria të mos e shpjerë në shpërfillje të Perëndisë."}]},{"title":"Kreu 82","blocks":[{"t":"p","x":"Dashuria e përsosur e dëbon frikën e parë prej shpirtit që ka fituar dashurinë, sepse ai nuk i druhet më dënimit. Por frikën e dytë, siç u tha, ajo e ka përherë të bashkuar me veten. Për frikën e parë vlejnë fjalët: «Nga frika e Zotit secili largohet prej së keqes» dhe: «Fillimi i urtësisë është frika e Zotit». Për të dytën vlejnë fjalët: «Frika e Zotit është e kulluar dhe mbetet në jetë të jetëve» dhe: «Ata që i druhen Atij s’kanë mungesë për asgjë»."}]},{"title":"Kreu 83","blocks":[{"t":"p","x":"«Bëjini të vdesin, pra, gjymtyrët tuaja që janë mbi tokë: kurvërinë, papastërtinë, pasionin, dëshirën e keqe dhe lakminë», e kështu me radhë. «Tokë» e quajti mendësinë e mishit. Me «kurvëri» kuptoi mëkatin e kryer me vepër. «Papastërti» quajti dhënien e pëlqimit. «Pasion» e quajti mendimin e ndezur nga pasioni. «Dëshirë të keqe» quajti thjesht pranimin e mendimit që sugjeron dëshirën. Me «lakmi» emërtoi atë lëndë prej së cilës lind e rritet pasioni. Të gjitha këto, pra, si gjymtyrë të mendësisë së mishit, Apostulli hyjnor na urdhëroi t’i bëjmë të vdesin."}]},{"title":"Kreu 84","blocks":[{"t":"p","x":"Në fillim, kujtesa i sjell mendjes një mendim të thjeshtë. Kur ky zë vend gjatë në mendje, ngjall pasionin. Nëse pasioni nuk asgjësohet, e përkul mendjen derisa ajo të japë pëlqimin. Pasi e jep pëlqimin, njeriu arrin më në fund te mëkati me vepër. Prandaj Apostulli fort i urtë, kur u shkruan të ardhurve nga paganizmi, i urdhëron të zhdukin së pari frytin e mëkatit dhe pastaj, duke i përshkuar hapat mbrapsht njëri pas tjetrit, të arrijnë deri te shkaku. Siç u tha, shkaku është lakmia, e cila e lind dhe e ushqen pasionin. Më duket se këtu fjala shënon grykësinë, sepse grykësia është nëna dhe mëndesha e kurvërisë. Lakmia është e keqe si për paranë, ashtu edhe për ushqimin, njësoj si vetëpërmbajtja që është e mirë si për ushqimin, ashtu edhe për paranë."}]},{"title":"Kreu 85","blocks":[{"t":"p","x":"Siç tërhiqet përdhe një zogth me këmbën të lidhur, që sapo nis të fluturojë ndien litarin ta tërheqë poshtë, ashtu edhe mendjen që ende nuk e ka fituar papasionshmërinë, sapo merr fluturimin drejt njohjes së gjërave qiellore, pasionet e tërheqin sërish në tokë."}]},{"title":"Kreu 86","blocks":[{"t":"p","x":"Kur mendja çlirohet plotësisht nga pasionet, ajo ecën, pa u kthyer më prapa, drejt soditjes së qenieve, duke e bërë këtë udhëtim për të arritur te njohja e Trinisë së Shenjtë."}]},{"title":"Kreu 87","blocks":[{"t":"p","x":"Kur është e pastër, mendja merr në vetvete përfytyrimet e gjërave dhe prej tyre ngrihet në soditjen e tyre shpirtërore. Por kur bëhet e papastër nga pakujdesia, gjërat e tjera i përfytyron thjesht ashtu siç i paraqiten, ndërsa përfytyrimet që kanë të bëjnë me njerëzit i kthen në mendime të turpshme a të liga."}]},{"title":"Kreu 88","blocks":[{"t":"p","x":"Kur, sa herë që lutesh, asnjë mendim i gjërave të botës nuk ta shqetëson mendjen, dije atëherë se ke hyrë brenda kufijve të papasionshmërisë."}]},{"title":"Kreu 89","blocks":[{"t":"p","x":"Kur shpirti nis të ndiejë se ka marrë shëndet, atëherë edhe përfytyrimet që sheh në gjumë nisin t’i shfaqen të zhveshura nga pasioni e të patrazuara."}]},{"title":"Kreu 90","blocks":[{"t":"p","x":"Sikurse bukuria e gjërave të dukshme e tërheq syrin trupor, ashtu njohja e të padukshmeve e tërheq drejt vetes mendjen e pastër. Me të padukshmet kuptoj qeniet patrupore."}]},{"title":"Kreu 91","blocks":[{"t":"p","x":"Gjë e madhe është të mos të të sundojë pasioni përballë vetë gjërave. Por shumë më e madhe është të mbetesh i lirë nga pasioni edhe përballë përfytyrimeve të tyre. Sepse lufta që na bëjnë demonët nëpërmjet mendimeve është më e rëndë se ajo që na bëjnë nëpërmjet vetë gjërave."}]},{"title":"Kreu 92","blocks":[{"t":"p","x":"Ai që i ka vënë në jetë virtytet dhe është pasuruar me njohje, meqenëse tashmë i dallon gjërat ashtu siç janë prej natyre, flet dhe vepron në gjithçka sipas gjykimit të drejtë, pa iu shmangur aspak. Sepse duke i përdorur gjërat me arsye ose pa arsye, bëhemi edhe ne ose të virtytshëm, ose të ligj."}]},{"title":"Kreu 93","blocks":[{"t":"p","x":"Shenjë e papasionshmërisë së plotë është që përfytyrimet e gjërave të ngjiten përherë në zemër të zhveshura nga pasioni, edhe kur trupi rri zgjuar, edhe kur fle."}]},{"title":"Kreu 94","blocks":[{"t":"p","x":"Duke i vënë në jetë urdhërimet, mendja zhvesh pasionet. Nëpërmjet soditjes shpirtërore të gjërave të dukshme, ajo zhvesh edhe përfytyrimet e gjërave të ngarkuara me pasion. Nëpërmjet njohjes së të padukshmeve lë pas soditjen e të dukshmeve, dhe nëpërmjet njohjes së Trinisë së Shenjtë lë pas edhe njohjen e të padukshmeve."}]},{"title":"Kreu 95","blocks":[{"t":"p","x":"Kur lind dielli dhe ndriçon botën, ai zbulon edhe veten, edhe gjërat që ndriçohen prej tij. Po kështu, kur Dielli i drejtësisë lind në mendjen e pastër, zbulon edhe veten, edhe arsyet e brendshme të gjithçkaje që ka ardhur e do të vijë në qenie prej Tij."}]},{"title":"Kreu 96","blocks":[{"t":"p","x":"Perëndinë e njohim nga veprat e Tij madhështore dhe nga përkujdesja e Tij për gjithçka që ekziston, ndërsa qenësia e Tij mbetet përtej njohjes sonë. Nëpërmjet këtyre veprave, si nëpër pasqyra, ne dallojmë mirësinë, urtësinë dhe fuqinë e Tij të pafund."}]},{"title":"Kreu 97","blocks":[{"t":"p","x":"Mendja e pastër qëndron ose te mendimet pa pasion për punët njerëzore, ose te soditja e natyrshme e gjërave të dukshme, ose tek ajo e të padukshmeve, ose te drita e Trinisë së Shenjtë."}]},{"title":"Kreu 98","blocks":[{"t":"p","x":"Kur mendja sodit gjërat e dukshme, ose shqyrton arsyet e brendshme të natyrës së tyre, ose ato që shenjohen nëpërmjet tyre, ose kërkon vetë Shkakun."}]},{"title":"Kreu 99","blocks":[{"t":"p","x":"Kur qëndron në soditjen e të padukshmeve, mendja kërkon edhe arsyet e brendshme të natyrës së tyre, edhe shkakun përse erdhën në qenie, edhe çfarë rrjedh prej këtej, edhe si veprojnë mbi to përkujdesja dhe gjykimi hyjnor."}]},{"title":"Kreu 100","blocks":[{"t":"p","x":"Kur mendja arrin në Perëndinë, ajo digjet nga malli dhe, së pari, kërkon të njohë qenësinë e Tij. Por në atë që është Perëndia në vetvete ajo nuk gjen çka t’ia plotësojë mallin, sepse kjo është njëlloj e pamundur dhe e paarritshme për çdo natyrë të krijuar. Megjithatë ajo gjen ngushëllim tek ato që i përkasin Atij: te përjetësia, pafundësia dhe pakufishmëria e Tij, te mirësia dhe urtësia, te fuqia e Tij që krijon, përkujdeset e gjykon gjithçka që ekziston. Vetëm këtë mund të rrokim tërësisht për Të, pafundësinë e Tij. Dhe fakti vetë që nuk dimë asgjë për Të është ta njohim përmbi mendjen, siç kanë thënë diku dy teologët, Grigori dhe Dionisi."}]}]},{"title":"Qindëshja e dytë","items":[{"title":"Kreu 1","blocks":[{"t":"p","x":"Kush e do me të vërtetë Perëndinë, patjetër lutet edhe pa u shpërqendruar. Dhe kush lutet pa u shpërqendruar aspak, e do me të vërtetë Perëndinë. Por nuk mund të lutet pa u shpërqendruar ai që e ka mendjen të mbërthyer pas ndonjë gjëje tokësore. Pra, ai që e ka mendjen të lidhur pas ndonjë gjëje tokësore nuk e do Perëndinë."}]},{"title":"Kreu 2","blocks":[{"t":"p","x":"Kur mendja qëndron gjatë te ndonjë send që kapin shqisat, me siguri ushqen ndaj tij ndonjë pasion, qoftë dëshirë, hidhërim, zemërim apo mëri. Nëse nuk ngrihet përmbi atë send, nuk mund të çlirohet nga ai pasion."}]},{"title":"Kreu 3","blocks":[{"t":"p","x":"Kur pasionet e pushtojnë mendjen, e lidhin pas gjërave lëndore dhe, pasi e ndajnë nga Perëndia, e bëjnë të merret vetëm me to. Por kur e pushton dashuria për Perëndinë, ajo ia zgjidh prangat dhe e bind të ngrihet përmbi gjërat që kapin shqisat e madje përmbi vetë jetën tonë të përkohshme."}]},{"title":"Kreu 4","blocks":[{"t":"p","x":"Puna e urdhërimeve është t’i zhveshë përfytyrimet e gjërave nga pasioni. Puna e leximit dhe e soditjes është ta çlirojë mendjen nga lënda e nga trajtat. Prej kësaj lind lutja e pashpërqendruar."}]},{"title":"Kreu 5","blocks":[{"t":"p","x":"Ushtrimi praktik i virtyteve nuk mjafton për ta çliruar plotësisht mendjen nga pasionet, aq sa të mund të lutet pa u shpërqendruar, nëse pas tij nuk vijnë radhazi edhe soditjet e ndryshme shpirtërore. Ushtrimi praktik e çliron mendjen vetëm nga mungesa e vetëpërmbajtjes dhe nga urrejtja, kurse soditjet e çlirojnë edhe nga harresa e padija. Kështu do të mund të lutet siç duhet."}]},{"title":"Kreu 6","blocks":[{"t":"p","x":"Lutja e pastër njeh dy gjendje kulmore. Njërën e përjetojnë ata që ushtrohen në virtyt, tjetrën ata që i janë dhënë soditjes. E para i lind shpirtit nga frika e Perëndisë dhe nga shpresa e mirë, e dyta nga dashuria e zjarrtë hyjnore dhe nga pastrimi më i lartë. Shenja e shkallës së parë është që mendja të shkëputet nga të gjitha mendimet e botës, të mblidhet brenda vetes e t’i bëjë lutjet pa u shpërqendruar e pa u trazuar, sikur vetë Perëndia të qëndrojë aty pranë saj, ashtu siç qëndron vërtet. Shenja e së dytës është që, në vetë hovin e lutjes, mendja të rrëmbehet nga drita hyjnore dhe e pafund, e të mos ndiejë më kurrgjë, as veten e vet, as ndonjë gjë tjetër që ekziston, përveç Atij që nëpërmjet dashurisë vepron një përndritje të tillë në të. Atëherë, edhe kur kthehet te mendimet për Perëndinë, merr përshtypje të kulluara e të qarta për Të."}]},{"title":"Kreu 7","blocks":[{"t":"p","x":"Njeriu mbahet fort pas asaj që do dhe i shpërfill të gjitha gjërat që i dalin përpara si pengesë, vetëm që të mos privohet prej saj. Kështu edhe ai që e do Perëndinë kujdeset për lutjen e pastër dhe flak prej vetes çdo pasion që e pengon të lutet."}]},{"title":"Kreu 8","blocks":[{"t":"p","x":"Kush e flak tej vetëdashjen, nënën e pasioneve, me ndihmën e Perëndisë i lë lehtë pas edhe pasionet e tjera, si zemërimin, hidhërimin, mërinë e të ngjashmet me to. Kurse kush është nën pushtetin e së parës, edhe pa dashur plagoset prej të tjerave. Vetëdashja është lidhja e pasionuar me trupin."}]},{"title":"Kreu 9","blocks":[{"t":"p","x":"Pesë janë arsyet për të cilat njerëzit e duan njëri-tjetrin, herë në mënyrë të lavdërueshme e herë në mënyrë të qortueshme. Ose për hir të Perëndisë, siç i do të gjithë i virtytshmi, dhe siç e do të virtytshmin edhe ai që vetë nuk është ende i tillë. Ose për shkak të natyrës, siç i duan prindërit fëmijët dhe fëmijët prindërit. Ose nga lavdidashja e kotë, siç e do ai që lëvdohet atë që i thur lavde. Ose nga dashuria për paranë, siç e do dikush të pasurin me shpresë se do të marrë diçka prej tij. Ose nga dashuria për kënaqësi, si ai që kërkon kënaqjen e barkut e të epshit. E para prej këtyre dashurive është e lavdërueshme, e dyta as e lavdërueshme, as e qortueshme, ndërsa të tjerat burojnë nga pasionet."}]},{"title":"Kreu 10","blocks":[{"t":"p","x":"Nëse disa i urren, kurse disa as i do as i urren, nëse disa i do, por me masë, e disa të tjerë i do fort, mësoje nga kjo pabarazi se je larg dashurisë së përsosur, e cila kërkon ta duash çdo njeri njëlloj."}]},{"title":"Kreu 11","blocks":[{"t":"p","x":"«Largohu nga e keqja dhe bëj të mirën». Domethënë, lufto kundër armiqve që t’i pakësosh pasionet, e pastaj rri syçelët që të mos shtohen prapë. Dhe përsëri, lufto për të fituar virtytet, pastaj rri syçelët që t’i ruash. Ky mund të jetë kuptimi i fjalëve «ta punojë dhe ta ruajë»."}]},{"title":"Kreu 12","blocks":[{"t":"p","x":"Ata që, me lejimin e Perëndisë, na vënë në tundim, ose ndezin fuqinë dëshiruese të shpirtit, ose trazojnë fuqinë zemëruese, ose errësojnë atë arsyetuese, ose ia mbulojnë trupin njeriut me dhembje, ose i rrëmbejnë të mirat materiale."}]},{"title":"Kreu 13","blocks":[{"t":"p","x":"Demonët ose na tundojnë vetë, ose armatosin kundër nesh ata që nuk i druhen Zotit. Na tundojnë vetë kur veçohemi nga njerëzit, siç e tunduan Zotin në shkretëtirë. Kur jetojmë mes njerëzve, na tundojnë nëpërmjet tyre, siç e tunduan Zotin nëpërmjet farisenjve. Por ne, duke e mbajtur vështrimin tek Ai që na është dhënë për shembull, le t’i zmbrapsim nga të dyja anët."}]},{"title":"Kreu 14","blocks":[{"t":"p","x":"Kur mendja nis të përparojë në dashurinë për Perëndinë, atëherë nis ta tundojë edhe demoni i blasfemisë. Ai i shtie në mendje të tilla gjëra, sa asnjë njeri nuk do të mund t’i sajonte, por vetëm djalli, ati i tyre. Këtë e bën nga smira për njeriun që do Perëndinë, me qëllim që ai të bjerë në dëshpërim, duke kujtuar se i ka menduar vetë gjëra të tilla, dhe të mos guxojë më të fluturojë drejt Tij me lutjen e zakonshme. Por i ligu nuk i afrohet me këtë aspak qëllimit të vet. Përkundrazi, na bën edhe më të palëkundur. Sepse, kur na luftojnë dhe u qëndrojmë përballë, dalim më të sprovuar e më të vërtetë në dashurinë për Perëndinë. I hyftë shpata e tij në vetë zemrën e tij dhe iu thyeftë harku!"}]},{"title":"Kreu 15","blocks":[{"t":"p","x":"Kur mendja u drejtohet gjërave të dukshme, ajo i njeh natyrshëm nëpërmjet shqisave. As mendja, as njohja sipas natyrës, as vetë gjërat, as shqisat nuk janë të këqija, sepse të gjitha janë vepra të Perëndisë. Ç’është, pra, e keqja? Pa dyshim, pasioni që i bashkëngjitet përfytyrimit të natyrshëm. Por nëse mendja rri zgjuar, ajo mund t’i përdorë përfytyrimet edhe pa atë pasion."}]},{"title":"Kreu 16","blocks":[{"t":"p","x":"Pasioni është një lëvizje e shpirtit kundër natyrës, drejt një dashurie të paarsyeshme ose një urrejtjeje pa gjykim për ndonjë gjë që kapin shqisat, apo për hir të saj. Kështu, për shembull, njeriu mund të ushqejë një dashuri të paarsyeshme për ushqimin, për një grua, për paranë, për lavdinë kalimtare a për diçka tjetër të ndjeshme, ose të dojë dikë për hir të këtyre. Po ashtu, mund të urrejë pa gjykim ndonjërën nga gjërat që thamë, a të urrejë dikë për shkak të tyre."}]},{"title":"Kreu 17","blocks":[{"t":"p","x":"Ose, përsëri, e keqja qëndron në përdorimin e gabuar të përfytyrimeve, pas të cilit vjen keqpërdorimi i vetë gjërave. Për shembull, në marrëdhënien me gruan, bashkimi kryhet drejt kur synon lindjen e fëmijëve. Ai, pra, që ka për qëllim kënaqësinë, gabon në mënyrën si e përdor bashkimin, sepse e quan të mirë atë që nuk është e mirë. Një njeri i tillë, kur bashkohet me gruan, e keqpërdor këtë marrëdhënie. Po kështu ndodh edhe me gjërat e tjera dhe përfytyrimet e tyre."}]},{"title":"Kreu 18","blocks":[{"t":"p","x":"Kur demonët ta nxjerrin mendjen nga dëlirësia dhe ta rrethojnë me mendime kurvërie, thuaji atëherë me lot Zotit tënd: «Më flakën tej, e tani më kanë rrethuar! O gëzimi im, shpëtomë nga ata që më kanë rrethuar!» Dhe do të shpëtosh."}]},{"title":"Kreu 19","blocks":[{"t":"p","x":"I rëndë është demoni i kurvërisë dhe sulmon me tërbim ata që luftojnë kundër këtij pasioni, sidomos kur tregohen të pakujdesshëm në mënyrën e jetesës e gjatë takimeve me gra. Sepse, pasi e ka joshur pa u ndier mendjen me ëmbëlsinë e kënaqësisë, më pas i vërsulet nëpërmjet kujtesës kur njeriu është tërhequr në heshtje. Ia ndez trupin dhe i nxjerr mendjes përpara gjithfarë trajtash, duke e grishur t’i japë pëlqimin mëkatit. Nëse nuk do që këto përfytyrime të zënë vend tek ti, merr përsipër agjërimin, mundin, agripninë dhe heshtjen e mirë, bashkë me lutjen e zjarrtë."}]},{"title":"Kreu 20","blocks":[{"t":"p","x":"Ata që kërkojnë përherë shpirtin tonë e kërkojnë nëpërmjet mendimeve të ngarkuara me pasion, që ta hedhin në mëkat, qoftë në mendje, qoftë me vepër. Por, kur ta gjejnë mendjen tonë të papërkulur para këtyre mendimeve, «do të turpërohen e do të mbulohen me faqe të zezë». Dhe kur ta gjejnë të dhënë pas soditjes shpirtërore, «do të zmbrapsen dhe sakaq do të turpërohen fort»."}]},{"title":"Kreu 21","blocks":[{"t":"p","x":"Shërbesën e dhjakut e përmbush ai që, si një ushtrues para garës, e përgatit mendjen për përpjekjet e shenjta dhe i dëbon prej saj mendimet e ngarkuara me pasion. Shërbesën e priftit e përmbush ai që e ndriçon mendjen për njohjen e qenieve dhe zhduk atë që rrejshëm quhet njohje. Shërbesën e episkopit e përmbush ai që, me miron e shenjtë të njohjes së Trinisë së Shenjtë dhe të adhurueshme, e çon mendjen në përsosje."}]},{"title":"Kreu 22","blocks":[{"t":"p","x":"Demonët ligështohen kur, nëpërmjet urdhërimeve, pasionet tona pakësohen. Dhe shuhen fare kur pasionet zhduken krejt nëpërmjet papasionshmërisë së shpirtit, sepse nuk gjejnë më atë që u jepte vend në shpirt dhe me të cilën i bënin luftë. Ky mund të jetë kuptimi i fjalëve: «Do të ligështohen e do të shuhen përpara fytyrës sate»."}]},{"title":"Kreu 23","blocks":[{"t":"p","x":"Disa njerëz përmbahen nga pasionet prej frikës nga njerëzit, disa nga lavdidashja e kotë, të tjerë nga vetëpërmbajtja. Të tjerë akoma çlirohen nga pasionet nëpërmjet gjykimeve të Perëndisë."}]},{"title":"Kreu 24","blocks":[{"t":"p","x":"Të gjitha fjalët e Zotit përfshijnë këto katër gjëra: urdhërimet, dogmat, paralajmërimet për dënim dhe premtimet. Për hir të tyre durojmë çdo ashpërsi të jetës, agjërime, agripni, fjetje përdhe, mund e djersë në shërbime, fyerje, çnderime, tortura, vdekje e të tjera si këto. Sepse «për hir të fjalëve të buzëve të tua», thotë psalmisti, «unë u jam përmbajtur udhëve të ashpra»."}]},{"title":"Kreu 25","blocks":[{"t":"p","x":"Shpërblimi i vetëpërmbajtjes është papasionshmëria, ndërsa i besimit njohja. Papasionshmëria lind aftësinë e dallimit, kurse njohja lind dashurinë për Perëndinë."}]},{"title":"Kreu 26","blocks":[{"t":"p","x":"Duke ushtruar drejt jetën praktike, mendja përparon në urtësinë e gjykimit, dhe duke ushtruar jetën soditëse, përparon në njohje. E para e çon atë që përpiqet deri tek aftësia për të dalluar virtytin nga ligësia. E dyta e shpie atë që merr pjesë në të tek arsyet e brendshme të qenieve patrupore dhe të atyre trupore. Kurse për hirin e teologjisë bëhet i denjë atëherë kur, pasi i ka kapërcyer të gjitha këto me krahët e dashurisë dhe ka arritur në Perëndinë, shqyrton nëpërmjet Shpirtit atë që mund të njihet për Të, për aq sa i është e mundur mendjes njerëzore."}]},{"title":"Kreu 27","blocks":[{"t":"p","x":"Kur merr përsipër të flasësh për Perëndinë, mos kërko të depërtosh në atë që Ai është në vetvete. Këtë s’ka për ta gjetur kurrë mendja e njeriut, as mendja e ndonjë qenieje tjetër pas Perëndisë. Por shqyrto, aq sa të mundesh, ato që i përkasin Atij, si përjetësia, pafundësia dhe pakufishmëria, mirësia e urtësia, fuqia e Tij që krijon, përkujdeset e gjykon gjithçka që ekziston. I madh ndër njerëz si teolog është ai që arrin t’ua gjejë qoftë edhe pjesërisht kuptimin këtyre gjërave."}]},{"title":"Kreu 28","blocks":[{"t":"p","x":"Burrë i fuqishëm është ai që ka bashkuar njohjen me veprën. Me veprën vyshk dëshirën e çrregullt dhe zbut zemërimin. Me njohjen i jep krahë mendjes dhe del prej vetes drejt Perëndisë."}]},{"title":"Kreu 29","blocks":[{"t":"p","x":"Kur Zoti thotë: «Unë dhe Ati jemi një», shpreh se qenësia e Tyre është një dhe e njëjtë. Kur përsëri thotë: «Unë jam në Atin dhe Ati është në mua», tregon pandashmërinë e hipostazave. Triteistët, pra, duke e ndarë Birin nga Ati, bien në një humnerë nga cilado anë të kthehen. Sepse, nëse thonë se Biri është bashkë i përjetshëm me Atin, por njëherësh e ndajnë prej Tij, detyrohen të thonë se nuk ka lindur prej Tij dhe bien në pohimin e tre perëndive dhe të tri parimeve. Nëse, nga ana tjetër, thonë se ka lindur prej Tij, por prapëseprapë e ndajnë, detyrohen të thonë se nuk është bashkë i përjetshëm me Atin dhe e vënë nën kohë të Zotin e kohëve. Sepse, sipas Grigorit të Madh, duhet edhe ta ruajmë besimin tek i vetmi Perëndi, edhe t’i pohojmë të tria hipostazat, secilën me vetinë e saj. Sepse, sipas fjalës së po atij Grigori, Hyjnia «ndahet» në mënyrë «të pandashme» dhe «bashkohet» duke «mbetur e dalluar». Prandaj edhe dallimi, edhe bashkimi i kapërcejnë mendimet tona. Se ç’do të kishte përtej mendjes, nëse Biri do të ishte i bashkuar me Atin dhe i ndarë prej Tij vetëm ashtu siç është i bashkuar e i ndarë një njeri nga një tjetër, e asgjë më tepër?"}]},{"title":"Kreu 30","blocks":[{"t":"p","x":"Kush është i përsosur në dashuri dhe ka arritur në kulmin e papasionshmërisë, nuk bën dallim midis të vetit dhe të huajit, midis gruas së afërt dhe asaj të huaj, midis besimtarit e jobesimtarit, skllavit e të lirit, madje as midis mashkullit e femrës. Duke u ngritur përmbi tiraninë e pasioneve dhe duke vështruar natyrën e vetme që u përket të gjithë njerëzve, ai i sheh të gjithë njëlloj dhe ushqen për të gjithë të njëjtat ndjenja. Sepse tek ai «nuk ka grek e jude, mashkull e femër, skllav e të lirë, por Krishti është gjithçka dhe në të gjithë»."}]},{"title":"Kreu 31","blocks":[{"t":"p","x":"Nga pasionet që fshihen në shpirt demonët marrin shkas për të zgjuar brenda nesh mendime të ngarkuara me pasion. Pastaj me këto mendime i bëjnë luftë mendjes dhe kërkojnë ta shtrëngojnë që t’i japë pëlqimin mëkatit. Kur ajo mposhtet, e çojnë te mëkati në mendime, dhe, kur ky është kryer, e marrin rob dhe më në fund e çojnë te vepra. Pasi e kanë shkretuar shpirtin nëpërmjet mendimeve, demonët tërhiqen bashkë me to. Në mendje mbetet vetëm idhulli i mëkatit, për të cilin Zoti thotë: «Kur të shihni neverinë e shkretimit duke qëndruar në vend të shenjtë, kush lexon, le të kuptojë». Mendja e njeriut është vend i shenjtë dhe tempull i Perëndisë. Aty vendosën demonët idhullin e mëkatit pasi e shkretuan shpirtin me mendimet e pasionuara. Se këto gjëra tashmë kanë ndodhur edhe në histori, besoj se nuk dyshon askush që ka lexuar veprat e Josifit. Megjithatë, disa thonë se do të ndodhin edhe në kohën e Antikrishtit."}]},{"title":"Kreu 32","blocks":[{"t":"p","x":"Tri gjëra na vënë në lëvizje drejt së mirës: farërat e mbjella në natyrën tonë, fuqitë e shenjta dhe zgjedhja e mirë. Farërat e natyrës veprojnë, për shembull, kur u bëjmë njerëzve atë që dëshirojmë të na bëjnë edhe ata, ose kur shohim dikë në ngushticë a në nevojë dhe vetvetiu na vjen keq për të. Fuqitë e shenjta veprojnë kur, pasi jemi nisur të bëjmë një punë të mirë, gjejmë mbështetje për të mirën dhe kemi mbarësi. Ndërsa zgjedhja e mirë vepron kur, pasi dallojmë të mirën nga e keqja, zgjedhim të mirën."}]},{"title":"Kreu 33","blocks":[{"t":"p","x":"Tri gjëra, nga ana tjetër, na vënë në lëvizje drejt së keqes: pasionet, demonët dhe zgjedhja e keqe. Pasionet veprojnë kur dëshirojmë diçka kundër arsyes, për shembull ushqim jashtë kohe a përtej nevojës, ose kur dëshirojmë një grua pa synuar lindjen e fëmijëve, madje një grua që nuk është bashkëshortja jonë e ligjshme. Veprojnë edhe kur zemërohemi a hidhërohemi pa të drejtë, për shembull me atë që na ka çnderuar a na ka dëmtuar. Demonët veprojnë kur përgjojnë çastin e pakujdesisë sonë dhe na sulmojnë papritur me furi të madhe, duke zgjuar pasionet e përmendura dhe të tjera si ato. Kurse zgjedhja e keqe vepron kur e njohim të mirën, por në vend të saj zgjedhim të keqen."}]},{"title":"Kreu 34","blocks":[{"t":"p","x":"Shpërblimet e mundimeve për hir të virtytit janë papasionshmëria dhe njohja. Këto na hapin rrugën drejt Mbretërisë së qiejve, sikurse pasionet dhe padija na çojnë drejt dënimit të përjetshëm. Ai, pra, që i kërkon këto shpërblime për lavdi nga njerëzit e jo për hir të vetë së mirës, le të dëgjojë prej Shkrimit: «Ju kërkoni dhe nuk merrni, sepse kërkoni keq»."}]},{"title":"Kreu 35","blocks":[{"t":"p","x":"Shumë vepra njerëzish janë të mira prej natyre, por mund të pushojnë së qeni të mira për shkak të qëllimit me të cilin bëhen. Agjërimi dhe agripnia, lutja dhe psalmodia, lëmosha dhe mikpritja janë vepra të mira prej natyre. Por kur bëhen nga lavdidashja e kotë, nuk janë më të mira."}]},{"title":"Kreu 36","blocks":[{"t":"p","x":"Në gjithçka që bëjmë, Perëndia kërkon qëllimin tonë, nëse veprojmë për hir të Tij apo për ndonjë arsye tjetër."}]},{"title":"Kreu 37","blocks":[{"t":"p","x":"Kur dëgjon Shkrimin të thotë: «Ti do t’ia shpërblesh secilit sipas veprave të tij», dije se Perëndia nuk u jep shpërblim të mirë veprave të kryera me qëllim të shtrembër, sado të mira të duken, por atyre që bëhen me qëllim të drejtë. Sepse gjykimi i Perëndisë vështron qëllimin për të cilin bëhen veprat, përtej dukjes së vetë veprës."}]},{"title":"Kreu 38","blocks":[{"t":"p","x":"Ligësia e demonit të krenarisë merr dy trajta. Ose përpiqet ta bindë murgun t’ia njohë vetes arritjet, pa ia njohur Perëndisë, që edhe ia fal të mirat, edhe e ndihmon t’i çojë në vend. Ose, kur murgu nuk i bindet, i shtie në mendje të përbuzë ata vëllezër që ende s’kanë përparuar sa ai. Kush bie nën këtë ndikim nuk e kupton se edhe kështu demoni po e bind të mohojë ndihmën e Perëndisë. Sepse në qoftë se i përbuz vëllezërit ngaqë nuk kanë mundur t’ia dalin, e paraqet veten si të kishte arritur me fuqitë e veta. Por kjo është e pamundur, sepse Zoti ka thënë: «Pa mua nuk mund të bëni asgjë». Dobësia jonë mund të marrë udhën drejt së mirës, por pa Atë që i dhuron të mirat nuk mund ta çojë veprën në fund."}]},{"title":"Kreu 39","blocks":[{"t":"p","x":"Kush ka njohur dobësinë e natyrës njerëzore ka provuar edhe fuqinë hyjnore. Me anë të saj ka arritur disa gjëra dhe po përpiqet të arrijë të tjera, prandaj kurrë nuk përbuz asnjë njeri. E di se, ashtu siç e ndihmoi atë vetë dhe e çliroi nga shumë pasione të rënda, Perëndia mund t’i ndihmojë të gjithë kur të dojë, sidomos ata që luftojnë për hir të Tij. E nëse, për arsye që i përkasin gjykimit të vet, nuk i çliron të gjithë përnjëherësh nga pasionet, si mjek i mirë e njeridashës, Ai shëron në kohën e duhur secilin prej atyre që përpiqen."}]},{"title":"Kreu 40","blocks":[{"t":"p","x":"Kur pasionet pushojnë së vepruari, mund të lindë krenaria, qoftë kur janë prerë shkaqet e pasioneve, qoftë kur demonët janë tërhequr me dredhi."}]},{"title":"Kreu 41","blocks":[{"t":"p","x":"Pothuajse çdo mëkat kryhet për kënaqësi. Dhe mëkati shlyhet nëpërmjet mundimit dhe hidhërimit, që njeriu ose i merr përsipër vullnetarisht nëpërmjet pendimit, ose i pëson pa dashje nëpërmjet një sprove që ia sjell përkujdesja hyjnore. «Sepse po ta gjykonim veten, nuk do të gjykoheshim. Por kur gjykohemi prej Zotit, ndreqemi, që të mos dënohemi bashkë me botën»."}]},{"title":"Kreu 42","blocks":[{"t":"p","x":"Kur të bjerë papritur një sprovë, mos fajëso njeriun nëpërmjet të cilit të erdhi. Kërko përse të erdhi, dhe do të gjesh si të ndreqesh. Sepse, qoftë nëpërmjet atij njeriu, qoftë nëpërmjet një tjetri, ti do ta pije medoemos pelinin e gjykimeve të Perëndisë."}]},{"title":"Kreu 43","blocks":[{"t":"p","x":"Për sa kohë që sjellja jote është e keqe, mos e kundërshto vuajtjen, që, i përulur prej saj, ta vjellësh nga vetja krenarinë."}]},{"title":"Kreu 44","blocks":[{"t":"p","x":"Disa tundime u sjellin njerëzve kënaqësi, të tjera hidhërime e të tjera dhembje trupore. Sepse Mjeku i shpirtrave, në gjykimet e veta, e vë edhe ilaçin sipas shkakut të pasioneve që gjendet brenda shpirtit."}]},{"title":"Kreu 45","blocks":[{"t":"p","x":"Disa njerëzve sprovat u vijnë për shlyerjen e mëkateve që kanë bërë, disave për zhdukjen e atyre që po kryejnë tani, kurse të tjerëve për t’u prerë udhën mëkateve që do të kryenin më pas. Veç këtyre janë edhe sprovat që vijnë për të vënë dikë në provë, si në rastin e Jovit."}]},{"title":"Kreu 46","blocks":[{"t":"p","x":"I urti, duke kuptuar se me gjykimet e veta Perëndia e shëron, i bart me falënderim fatkeqësitë që i bien dhe për to nuk bën fajtor tjetërkënd, përveç mëkateve të veta. Kurse i pamendi, duke mos e njohur përkujdesjen plot urtësi të Perëndisë, kur mëkaton e merr ndreqje, për të këqijat e veta bën fajtor ose Perëndinë, ose njerëzit."}]},{"title":"Kreu 47","blocks":[{"t":"p","x":"Disa gjëra i ndalin pasionet në hovin e tyre dhe nuk i lënë të rriten. Të tjera i dobësojnë e i bëjnë të pakësohen. Për shembull, agjërimi, mundi dhe agripnia nuk e lënë dëshirën e çrregullt të shtohet. Tërheqja në vetmi, soditja, lutja dhe dashuria e zjarrtë për Perëndinë e dobësojnë derisa ta shuajnë. Po kështu edhe me zemërimin. Zemërgjerësia në durim, lënia e mërisë dhe butësia e ndalin dhe nuk e lënë të shtohet, kurse dashuria, lëmosha, mirësia dhe njeridashja e pakësojnë."}]},{"title":"Kreu 48","blocks":[{"t":"p","x":"Tek ai që e ka mendjen përherë të kthyer nga Perëndia, dëshira është rritur aq sa është bërë mall i zjarrtë për Hyjninë dhe e tërë fuqia e zemërimit është shndërruar në dashuri hyjnore. Sepse mendja, duke marrë pjesë gjatë në përndritjen hyjnore, është bërë e tëra si dritë. Ajo ka lidhur ngushtë me veten edhe atë pjesë të shpirtit që përjeton pasionet dhe, duke e kthyer tërësisht nga gjërat tokësore te Hyjnia, e ka shndërruar, siç u tha, në mall hyjnor të patregueshëm e në dashuri të pareshtur."}]},{"title":"Kreu 49","blocks":[{"t":"p","x":"Edhe nëse dikush nuk e ka zili, nuk zemërohet e nuk mban mëri ndaj atij që e ka hidhëruar, prej kësaj nuk del medoemos se ka tashmë dashuri për të. Edhe ai që ende nuk e do tjetrin mund, për hir të urdhërimit, të mos ia kthejë të keqen me të keqe. Por kjo nuk do të thotë medoemos se mund t’ia kthejë natyrshëm të keqen me të mirë. T’u bësh mirë me gjithë zemër atyre që të urrejnë i përket vetëm dashurisë së përsosur shpirtërore."}]},{"title":"Kreu 50","blocks":[{"t":"p","x":"Kush nuk e do një njeri, nuk do të thotë se patjetër e urren. Po ashtu, kush nuk e urren, nuk do të thotë se patjetër e do. Mundet edhe të qëndrojë në mes, domethënë as ta dojë, as ta urrejë. Sepse një prirje dashurie mund ta ngjallin vetëm ato pesë mënyra që u përmendën në kapitullin e nëntë të kësaj qindësheje, e lavdërueshmja, ajo e ndërmjetmja dhe të qortueshmet."}]},{"title":"Kreu 51","blocks":[{"t":"p","x":"Kur sheh se mendja jote merret me kënaqësi me gjërat lëndore dhe qëndron me ëndje në përfytyrimet e tyre, dije se i do ato më shumë se Perëndinë. «Sepse atje ku është thesari yt», thotë Zoti, «atje do të jetë edhe zemra jote»."}]},{"title":"Kreu 52","blocks":[{"t":"p","x":"Mendja që bashkohet me Perëndinë dhe qëndron gjatë me Të nëpërmjet lutjes e dashurisë, bëhet e urtë, e mirë, e fuqishme, njeridashëse, e mëshirshme dhe zemërgjerë në durim. Me një fjalë, mbart në vete pothuajse të gjitha vetitë hyjnore. Por kur largohet prej Tij dhe u afrohet gjërave lëndore, ose bëhet si kafsha shtëpiake duke rrojtur për kënaqësinë, ose bëhet si bisha e egër duke luftuar kundër njerëzve për hir të atyre gjërave."}]},{"title":"Kreu 53","blocks":[{"t":"p","x":"Shkrimi quan «botë» gjërat lëndore dhe njerëz «të botës» ata që e mbajnë mendjen të zënë me to. Këta i qorton me fjalët: «Mos e doni botën, as ato që janë në botë. Dëshira e mishit, dëshira e syve dhe mburrja e jetës nuk janë prej Perëndisë, por prej botës», e kështu me radhë."}]},{"title":"Kreu 54","blocks":[{"t":"p","x":"Murg është ai që e ka shkëputur mendjen nga gjërat lëndore dhe, nëpërmjet vetëpërmbajtjes, dashurisë, psalmodisë dhe lutjes, qëndron besnik pranë Perëndisë."}]},{"title":"Kreu 55","blocks":[{"t":"p","x":"Në kuptimin shpirtëror, ai që ushtrohet në virtyt është mbarështues bagëtish, sepse bagëtitë përfaqësojnë arritjet në jetën e virtytshme. Prandaj edhe Jakovi thoshte: «Shërbëtorët e tu janë mbarështues bagëtish». Kurse ai që ka arritur njohjen shpirtërore është bari dhensh, sepse delet përfaqësojnë mendimet që mendja i nxjerr për kullotë në malet e soditjeve. Prandaj është thënë edhe: «Çdo bari dhensh është i neveritshëm për egjiptianët», domethënë për fuqitë kundërshtare."}]},{"title":"Kreu 56","blocks":[{"t":"p","x":"Kur trupi, i nxitur nga shqisat, kthehet drejt dëshirave dhe kënaqësive të veta, mendja e rënë në ligësi e ndjek nga pas dhe u jep pëlqimin përfytyrimeve e hoveve të trupit. Kurse mendja e virtytshme ushtron vetëpërmbajtje, e frenon trupin përballë përfytyrimeve e hoveve të ngarkuara me pasion dhe, përkundrazi, kërkon me urtësi t’i drejtojë për mirë këto lëvizje të tij."}]},{"title":"Kreu 57","blocks":[{"t":"p","x":"Disa virtyte janë trupore, disa shpirtërore. Ndër truporet janë agjërimi, agripnia, fjetja përdhe, shërbimi, puna e duarve për të mos iu bërë barrë ndokujt ose për t’u dhënë të tjerëve, e të tjera si këto. Ndër shpirtëroret janë dashuria, zemërgjerësia në durim, butësia, vetëpërmbajtja, lutja e të tjera. Nëse, pra, për ndonjë nevojë a gjendje trupore, për shembull një sëmundje a diçka të ngjashme, ndodh që nuk mund t’i ushtrojmë virtytet trupore të përmendura, kemi ndjesë nga Ai që i njeh edhe shkaqet. Por nëse nuk ushtrojmë virtytet shpirtërore, nuk do të kemi asnjë përligjje, sepse ato nuk varen nga një detyrim i tillë i jashtëm."}]},{"title":"Kreu 58","blocks":[{"t":"p","x":"Dashuria për Perëndinë e bind atë që merr pjesë në të të ngrihet përmbi çdo kënaqësi kalimtare, përmbi çdo mundim dhe hidhërim. Le të të bindin për këtë të gjithë shenjtorët, të cilët për hir të Krishtit i përballuan me gëzim gjithë ato vuajtje."}]},{"title":"Kreu 59","blocks":[{"t":"p","x":"Ruaju nga vetëdashja, nëna e të këqijave, e cila është dashuria e paarsyeshme për trupin. Prej saj lindin, nën petkun e një arsyetimi në dukje të drejtë, tri mendimet e para dhe më të përgjithshme të ngarkuara me pasion: ai i grykësisë, ai i dashurisë për paranë dhe ai i lavdidashjes së kotë. Secili gjoja merr shkas nga një nevojë e domosdoshme e trupit. Prej tyre lind mbarë vargu i të këqijave. Duhet, pra, siç u tha, të ruhemi medoemos nga vetëdashja dhe ta luftojmë me vigjilencë të madhe. Sepse kur ajo shkulet, bashkë me të shkulen të gjitha mendimet që kanë lindur prej saj."}]},{"title":"Kreu 60","blocks":[{"t":"p","x":"Pasioni i vetëdashjes i pëshpërit murgut të ketë keqardhje për trupin e vet e t’i bëjë lëshime në ushqim përtej masës së duhur, gjoja nga përkujdesja e urtë për ta mbajtur trupin në këmbë. Kështu, pak nga pak, e merr rryma, derisa bie në gropën e dashurisë për kënaqësitë. Ndërsa njeriut të botës vetëdashja i shtie menjëherë në mendje të kujdeset për trupin që t’ia kënaqë dëshirat."}]},{"title":"Kreu 61","blocks":[{"t":"p","x":"Thonë se shkalla më e lartë e lutjes është kjo: ndërsa lutet, mendja të dalë përtej mishit dhe botës, e zhveshur krejt nga lënda e nga trajtat. Kush e ruan të pacenuar këtë gjendje, ai me të vërtetë lutet pa pushim."}]},{"title":"Kreu 62","blocks":[{"t":"p","x":"Siç ndahet trupi, kur vdes, nga të gjitha gjërat e botës, ashtu edhe mendja, duke vdekur në kulmin e lutjes, ndahet nga të gjitha përfytyrimet e gjërave të botës. Sepse, pa e përjetuar një vdekje të tillë, ajo nuk mund të gjendet e të jetojë me Perëndinë."}]},{"title":"Kreu 63","blocks":[{"t":"p","x":"O murg, mos të të gënjejë askush se mund të shpëtosh duke u shërbyer kënaqësisë dhe lavdidashjes së kotë."}]},{"title":"Kreu 64","blocks":[{"t":"p","x":"Siç mëkaton trupi nëpërmjet vetë gjërave dhe ka për mësues virtytet trupore që të mësojë dëlirësinë, ashtu mëkaton edhe mendja nëpërmjet përfytyrimeve të ngarkuara me pasion. Edhe ajo ka për mësues virtytet shpirtërore, që të qëndrojë e dëlirë, duke i parë gjërat me pastërti e pa pasion."}]},{"title":"Kreu 65","blocks":[{"t":"p","x":"Siç vijnë netët pas ditëve dhe dimrat pas verave, ashtu edhe pas lavdidashjes së kotë dhe kënaqësisë vijnë hidhërimet dhe dhembjet, qoftë në këtë jetë, qoftë në atë që do të vijë."}]},{"title":"Kreu 66","blocks":[{"t":"p","x":"Kush ka mëkatuar, nuk mund t’i shpëtojë gjykimit të ardhshëm pa marrë mbi vete këtu mundime me dashjen e vet, ose pa përballuar sprova që i vijnë pa dashjen e tij."}]},{"title":"Kreu 67","blocks":[{"t":"p","x":"Thonë se për pesë arsye Perëndia lejon që demonët të na luftojnë. E para, që duke u sulmuar dhe duke i qëndruar përballë sulmit, të arrijmë të dallojmë virtytin nga ligësia. E dyta, që virtytin e fituar me luftë e mundim ta kemi të qëndrueshëm e të patundur. E treta, që, ndërsa përparojmë në virtyt, të mos mbahemi me të madh, por të mësojmë përulësinë. E katërta, që, pasi ta kemi provuar të keqen, ta urrejmë me urrejtje të plotë. E pesta, përmbi të gjitha, që kur të jemi çliruar nga pasionet, të mos harrojmë as dobësinë tonë, as fuqinë e Atij që na ndihmoi."}]},{"title":"Kreu 68","blocks":[{"t":"p","x":"Siç i shkon mendja për bukë atij që ka uri dhe për ujë atij që ka etje, kështu mendja e grykësit përfytyron gjellë të shumëllojshme, e atij që do kënaqësitë, trajta grash, e lavdidashësit të kotë, nderimet që japin njerëzit, e atij që do paranë, fitime, e atij që mban mëri, hakmarrjen ndaj atij që e hidhëroi, dhe e smirëziut, të keqen që i bie atij që ai ka zili. Kështu ndodh edhe me pasionet e tjera. Sepse mendja e trazuar prej pasioneve merr përfytyrime të ngarkuara me pasion, edhe kur trupi është zgjuar, edhe në gjumë."}]},{"title":"Kreu 69","blocks":[{"t":"p","x":"Kur shtohet dëshira e çrregullt, mendja përfytyron në gjumë ato gjëra që sjellin kënaqësi. Kur shtohet zemërimi, ajo sheh gjëra që ngjallin frikë. Demonët e papastër i shtojnë pasionet, duke i ngacmuar dhe duke pasur për bashkëpunëtore pakujdesinë tonë. Engjëjt e shenjtë, nga ana tjetër, i pakësojnë pasionet duke na nxitur t’i vëmë në jetë virtytet."}]},{"title":"Kreu 70","blocks":[{"t":"p","x":"Kur fuqia dëshiruese e shpirtit ngacmohet shpesh, ajo rrënjos në shpirt një prirje për kënaqësi që mezi shkulet. Kur fuqia e zemërimit trazohet vazhdimisht, e bën mendjen të frikësuar dhe i heq guximin. Të parën e shëron ushtrimi i zellshëm në agjërim, në agripni e në lutje. Të dytën e shërojnë mirësia, njeridashja, dashuria dhe mëshira."}]},{"title":"Kreu 71","blocks":[{"t":"p","x":"Demonët luftojnë ose me anë të vetë gjërave, ose me anë të përfytyrimeve të tyre të ngarkuara me pasion. Me anë të gjërave luftojnë ata që jetojnë mes tyre, kurse me anë të përfytyrimeve ata që janë veçuar prej gjërave."}]},{"title":"Kreu 72","blocks":[{"t":"p","x":"Sa më e lehtë është të mëkatosh në mendje sesa me vepër, aq më e rëndë është lufta që bëhet nëpërmjet përfytyrimeve sesa ajo që bëhet nëpërmjet vetë gjërave."}]},{"title":"Kreu 73","blocks":[{"t":"p","x":"Gjërat janë jashtë mendjes, kurse përfytyrimet e tyre marrin trajtë brenda saj. Prandaj nga mendja varet nëse do t’i përdorë mirë apo keq. Sepse përdorimit të shtrembër të përfytyrimeve i vjen pas keqpërdorimi i vetë gjërave."}]},{"title":"Kreu 74","blocks":[{"t":"p","x":"Në tri mënyra i merr mendja përfytyrimet e ngarkuara me pasion: nëpërmjet shqisave, nëpërmjet gjendjes së trupit dhe nëpërmjet kujtesës. Nëpërmjet shqisave, kur gjërat pas të cilave jemi lidhur me pasion na dalin përpara shqisave dhe e nxitin mendjen drejt mendimeve të pasionuara. Nëpërmjet gjendjes së trupit, kur kjo gjendje pëson ndryshim nga një jetë e shthurur, nga veprimi i demonëve apo nga ndonjë sëmundje, dhe e nxit sërish mendjen drejt mendimeve të pasionuara ose të mendimeve kundër përkujdesjes hyjnore. Nëpërmjet kujtesës, kur ajo sjell sërish ndër mend përfytyrimet e gjërave pas të cilave jemi lidhur me pasion dhe po ashtu ngjall në mendje mendime të pasionuara."}]},{"title":"Kreu 75","blocks":[{"t":"p","x":"Ndër gjërat që Perëndia na ka dhënë për t’i përdorur, disa gjenden në shpirt, disa në trup e disa përreth trupit. Në shpirt gjenden fuqitë e tij. Në trup, organet e shqisave dhe gjymtyrët e tjera. Përreth trupit, ushqimet, të hollat, pronat e të ngjashmet me to. Nëse i përdorim mirë apo keq këto gjëra, ose atë që lidhet me to, kjo na shfaq si njerëz të virtytshëm ose të ligj."}]},{"title":"Kreu 76","blocks":[{"t":"p","x":"Edhe ato që u ndodhin këtyre gjërave u përkasin ose gjërave të shpirtit, ose atyre të trupit, ose atyre përreth trupit. Shpirtit i përkasin, për shembull, njohja dhe padija, harresa dhe kujtesa, dashuria dhe urrejtja, frika dhe guximi, hidhërimi dhe gëzimi. Trupit i përkasin kënaqësia dhe dhembja, aftësia për të ndier dhe humbja e saj, shëndeti dhe sëmundja, jeta dhe vdekja, e të tjera si këto. Përreth trupit janë bekimi me fëmijë dhe mungesa e fëmijëve, pasuria dhe varfëria, fama dhe mungesa e saj e të ngjashmet. Disa nga këto njerëzit i quajnë të mira, disa të këqija, por asnjëra prej tyre nuk është e keqe për vetë atë që është. Nga mënyra si përdoret del nëse është vërtet e keqe apo e mirë."}]},{"title":"Kreu 77","blocks":[{"t":"p","x":"Njohja është e mirë prej natyre, po kështu edhe shëndeti. Megjithatë, shumë njerëzve u kanë bërë më tepër dobi të kundërtat e tyre. Për të ligjtë njohja nuk del për mirë, megjithëse, siç u tha, është e mirë prej natyre. Po ashtu nuk u del për mirë as shëndeti, as pasuria, as gëzimi, sepse nuk dinë t’i përdorin për të mirën e vet. Atyre, pra, u bëjnë dobi të kundërtat. Këto të fundit, atëherë, sado të këqija të duken, nuk janë të këqija për vetë atë që janë."}]},{"title":"Kreu 78","blocks":[{"t":"p","x":"Mos i keqpërdor përfytyrimet, që të mos përfundosh medoemos duke keqpërdorur edhe vetë gjërat. Sepse, po të mos mëkatonte njeriu më parë në mendje, kurrë nuk do të mëkatonte me vepër."}]},{"title":"Kreu 79","blocks":[{"t":"p","x":"Veset themelore, si pamendësia, frikacakëria, shthurja e padrejtësia, janë shëmbëllesa e njeriut prej dheu. Virtytet themelore, si urtësia e gjykimit, trimëria, dëlirësia dhe drejtësia, janë shëmbëllesa e Njeriut qiellor. Por «siç kemi mbartur shëmbëllesën e atij që është prej dheu, le të mbartim edhe shëmbëllesën e Atij që është qiellor»."}]},{"title":"Kreu 80","blocks":[{"t":"p","x":"Nëse dëshiron të gjesh udhën që të çon në jetë, kërkoje tek Ai që është Udha dhe atje do ta gjesh, tek Ai që tha: «Unë jam udha, e vërteta dhe jeta». Por kërkoje me shumë mund, sepse të paktë janë ata që e gjejnë. Ruhu që, duke mbetur jashtë atyre të paktëve, të mos gjendesh ndër të shumtët."}]},{"title":"Kreu 81","blocks":[{"t":"p","x":"Pesë gjëra e frenojnë shpirtin nga mëkatet: ose frika nga njerëzit, ose frika nga gjykimi, ose shpërblimi që do të vijë, ose dashuria për Perëndinë, ose, së fundi, ndërgjegjja që e godet."}]},{"title":"Kreu 82","blocks":[{"t":"p","x":"Disa thonë se e keqja nuk do të ekzistonte ndër qenie po të mos kishte një fuqi tjetër që na tërheq drejt saj. Por kjo fuqi s’është gjë tjetër veçse shpërfillja e veprimtarive që i përkasin mendjes sipas natyrës. Prandaj ata që kujdesen për këto veprimtari bëjnë përherë të mirën dhe kurrë të keqen. Nëse dëshiron, pra, edhe ti, flake tej pakujdesinë dhe bashkë me të do të dëbosh ligësinë, e cila është përdorimi i gabuar i përfytyrimeve, pas të cilit vjen keqpërdorimi i vetë gjërave."}]},{"title":"Kreu 83","blocks":[{"t":"p","x":"I përket natyrës së pjesës sonë të arsyeshme t’i nënshtrohet Fjalës hyjnore dhe të sundojë mbi pjesën e paarsyeshme brenda nesh. Le të ruhet ky rregull në gjithçka, dhe as e keqja nuk do të jetë ndër qenie, as nuk do të gjendet ndonjë gjë që të na tërheqë drejt saj."}]},{"title":"Kreu 84","blocks":[{"t":"p","x":"Disa mendime janë të thjeshta, disa të përbëra. Të thjeshta janë ato pa pasion, të përbëra ato të pasionuara, sepse përbëhen nga një pasion dhe një përfytyrim. Duke qenë kështu, mund të shohim se, kur mendimet e përbëra nisin ta shtyjnë njeriun drejt mëkatit në mendje, shumë mendime të thjeshta u shkojnë pas. Le të marrim arin. Dikujt iu zgjua në kujtesë një mendim i pasionuar për arin, e në mendjen e vet u hodh ta vidhte dhe e kreu mendërisht mëkatin. Por bashkë me kujtimin e arit i erdhën në mend edhe qesja, edhe sënduku, edhe dhoma e të tjera hollësi. Kujtimi i arit ishte i përbërë, sepse mbante brenda pasionin. Kurse kujtimi i qeses, i sëndukut e i gjërave të tjera ishte i thjeshtë, sepse për to mendja nuk ushqente ndonjë pasion. Po kështu është me çdo mendim tjetër, qoftë për lavdinë e kotë, për një grua a për gjëra të tjera. Pra, siç u tregua, jo të gjitha mendimet që shoqërojnë një mendim të pasionuar janë edhe vetë të pasionuara. Nga këto mund të njohim cilat përfytyrime janë të pasionuara e cilat të thjeshta."}]},{"title":"Kreu 85","blocks":[{"t":"p","x":"Disa thonë se demonët, duke prekur pjesët e trupit gjatë gjumit, ngacmojnë pasionin e kurvërisë. Pastaj ky pasion, pasi vihet në lëvizje, nëpërmjet kujtesës i sjell mendjes trajtën e gruas. Të tjerë thonë se demonët i shfaqen mendjes në trajtë gruaje dhe, duke prekur pjesët e trupit, zgjojnë epshin. Kështu lindin përfytyrimet. Të tjerë përsëri thonë se pasioni që mbizotëron në demonin që afrohet, zgjon po atë pasion te njeriu, dhe kështu shpirti ndizet e i kthehet mendimeve, duke sjellë nëpërmjet kujtesës trajtat përkatëse. Edhe për përfytyrimet e tjera të pasionuara, disa shpjegojnë se lindin në një mënyrë e disa në një tjetër. Megjithatë, kur në shpirt janë të pranishme dashuria dhe vetëpërmbajtja, demonët nuk kanë fuqi të zgjojnë asnjë pasion me asnjë nga mënyrat e përmendura, as kur trupi rri zgjuar, as kur fle."}]},{"title":"Kreu 86","blocks":[{"t":"p","x":"Disa nga urdhërimet e Ligjit duhen ruajtur edhe trupërisht, edhe shpirtërisht, kurse disa vetëm shpirtërisht. Për shembull, «mos shkel kurorën», «mos vrit», «mos vidh» e të ngjashmet duhen ruajtur edhe trupërisht, edhe shpirtërisht, madje shpirtërisht në tri mënyra. Por rrethprerja, ruajtja e së shtunës, therja e qengjit, ngrënia e bukëve të ndorme me barishte të hidhura e të tjera si këto duhen ruajtur vetëm shpirtërisht."}]},{"title":"Kreu 87","blocks":[{"t":"p","x":"Në jetën e murgjve dallohen tri gjendje kryesore të sjelljes. E para, të mos mëkatosh aspak me vepër. E dyta, të mos u lësh mendimeve të pasionuara kohë të zënë vend në shpirt. E treta, t’i soditësh pa pasion në mendje edhe fytyrat e grave, edhe fytyrat e atyre që të kanë hidhëruar."}]},{"title":"Kreu 88","blocks":[{"t":"p","x":"Njeri pa pronë është ai që ka hequr dorë nga të gjitha zotërimet e veta dhe nuk ka më asgjë mbi dhé përveç trupit të tij. Pasi ka këputur edhe lidhjen që e mban të kapur pas trupit, ai ia ka besuar Perëndisë dhe njerëzve të devotshëm kujdesin për veten."}]},{"title":"Kreu 89","blocks":[{"t":"p","x":"Ndër ata që zotërojnë pasuri, disa e zotërojnë pa pasion, prandaj edhe kur ua marrin, nuk hidhërohen. Të tillë ishin ata që e pritën «me gëzim grabitjen e pasurisë së tyre». Të tjerë e zotërojnë me pasion dhe, kur u duhet të ndahen prej saj, i mbulon trishtimi, si i pasuri në Ungjill, që u largua i hidhëruar. E po t’u hiqet vërtet, hidhërohen gjer në vdekje. Humbja e pasurisë, pra, vë në dukje se si e ka shpirtin edhe ai që është i lirë nga pasioni, edhe ai që është i lidhur prej tij."}]},{"title":"Kreu 90","blocks":[{"t":"p","x":"Ata që kanë arritur në kulmin e lutjes, demonët i luftojnë që të mos i marrin të zhveshura nga pasioni përfytyrimet e gjërave që kapin shqisat. Ata që kanë arritur njohjen shpirtërore i luftojnë që mendimet e pasionuara të zënë vend gjatë në ta. Ata që përpiqen në ushtrimin e virtytit i luftojnë për t’i bindur të mëkatojnë me vepër. Kundër të gjithëve luftojnë në çdo mënyrë të mjerët, vetëm e vetëm që t’i ndajnë njerëzit nga Perëndia."}]},{"title":"Kreu 91","blocks":[{"t":"p","x":"Ata që përkujdesja hyjnore i ushtron në këtë jetë për të jetuar me perëndishmëri, vihen në provë me këto tri lloje sprovash. Së pari, duke marrë gjëra të këndshme, si shëndeti, bukuria, bekimi me fëmijë, pasuria, fama e të ngjashmet me to. Së dyti, kur mbi ta bien ngjarje të hidhura, si humbja e fëmijëve, e pasurisë ose e nderimit. Së treti, kur u bien ato që i shkaktojnë dhembje trupit, si sëmundjet, torturat e të tjera. Atyre që vihen në provë me të parat, Zoti u thotë: «Kush nuk heq dorë nga gjithçka që ka, nuk mund të jetë nxënësi im». Kurse atyre që sprovohen në mënyrën e dytë dhe të tretë u thotë: «Me durimin tuaj fitojini shpirtrat tuaj»."}]},{"title":"Kreu 92","blocks":[{"t":"p","x":"Thonë se katër gjëra e ndryshojnë gjendjen e trupit dhe, nëpërmjet saj, i sjellin mendjes mendime, qoftë të pasionuara, qoftë pa pasion: engjëjt, demonët, ajri dhe mënyra e të ushqyerit. Engjëjt, thonë, e ndryshojnë gjendjen e trupit me fjalë, demonët me prekje, ajri përmes ndryshimeve të tij, ndërsa ushqimi nëpërmjet cilësisë së të ngrënave e të pirave dhe teprisë ose pakësisë së tyre. Këtu nuk hyjnë ndryshimet që i ndodhin trupit nëpërmjet kujtesës, dëgjimit dhe shikimit, kur më parë është prekur shpirti nga ngjarje të hidhura ose të gëzueshme që i kanë ndodhur. Në këto raste, shpirti që i përjeton ato ndryshon gjendjen e trupit. Në rastet e përmendura më parë ndodh e anasjellta: gjendja e ndryshuar e trupit i sjell mendjes mendime."}]},{"title":"Kreu 93","blocks":[{"t":"p","x":"Vdekja në kuptimin e mirëfilltë është ndarja nga Perëndia. Thumb i vdekjes është mëkati. Kur Adami e pranoi atë thumb, u dëbua njëherësh larg pemës së jetës, larg parajsës dhe larg Perëndisë. Pas kësaj erdhi pashmangshëm edhe vdekja e trupit. Jeta në kuptimin e mirëfilltë është Ai që tha: «Unë jam jeta». Ai hyri në vdekje dhe atë që kishte vdekur e solli përsëri në jetë."}]},{"title":"Kreu 94","blocks":[{"t":"p","x":"Kush merr e shkruan një fjalë, e shkruan ose për t’ia kujtuar diçka vetvetes, ose për dobinë e të tjerëve, ose për të dyja bashkë. Mund ta shkruajë edhe për të dëmtuar dikë, për të dalë në dukje ose nga nevoja."}]},{"title":"Kreu 95","blocks":[{"t":"p","x":"«Vend i gjelbëruar» është virtyti i vënë në jetë. «Ujë prehjeje» është njohja e gjërave të krijuara."}]},{"title":"Kreu 96","blocks":[{"t":"p","x":"«Hije vdekjeje» është jeta njerëzore. Nëse, pra, një njeri është me Perëndinë dhe Perëndia me të, atëherë ai mund t’i thotë me siguri të plotë këto fjalë: «Edhe sikur të eci përmes hijes së vdekjes, nuk do t’u druhem të këqijave, sepse Ti je me mua»."}]},{"title":"Kreu 97","blocks":[{"t":"p","x":"Mendja e pastër i sheh gjërat drejt. Fjala e ushtruar i nxjerr para syve gjërat që janë parë. Veshi i kthjellët i pranon. Por kush nuk i ka këto të tria, i gjen faj atij që ka folur."}]},{"title":"Kreu 98","blocks":[{"t":"p","x":"Me Perëndinë është ai që njeh Trininë e Shenjtë, veprën e saj krijuese e përkujdesjen e saj, dhe e ka çliruar nga pasionet atë pjesë të shpirtit që u nënshtrohet atyre."}]},{"title":"Kreu 99","blocks":[{"t":"p","x":"Thonë se «shkopi» shenjon gjykimin e Perëndisë, ndërsa «kërraba e bariut» përkujdesjen e Tij. Atij, pra, që ka marrë pjesë në njohjen e të dyjave, i përket të thotë: «Shkopi yt dhe kërraba jote, ato më ngushëlluan»."}]},{"title":"Kreu 100","blocks":[{"t":"p","x":"Kur mendja zhvishet nga pasionet dhe ndriçohet nga soditja e qenieve, atëherë mund të arrijë në Perëndinë dhe të lutet siç duhet."}]}]},{"title":"Qindëshja e tretë","items":[{"title":"Kreu 1","blocks":[{"t":"p","x":"Përdorimi i arsyeshëm i mendimeve dhe i gjërave lind dëlirësi, dashuri e njohje. Përdorimi i paarsyeshëm lind shthurje, urrejtje e padije."}]},{"title":"Kreu 2","blocks":[{"t":"p","x":"«Shtrove para meje një tryezë», e ç’thuhet më tej. Tryeza këtu shënon virtytin e ushtruar me vepra, sepse këtë tryezë na e shtroi Krishti përballë atyre që na mundojnë. Vaji që lyen mendjen shënon soditjen e gjërave të krijuara. Kupa e Perëndisë shënon njohjen e Perëndisë, ndërsa mëshira e Tij shënon Fjalën e Tij, që është Perëndi. Sepse, me anë të bërjes së Tij njeri, Ai u vihet pas ditë për ditë atyre që do të shpëtojnë, derisa t’i arrijë të gjithë, sikurse arriti Pavlin. Shtëpia shënon mbretërinë, ku të gjithë shenjtorët gjejnë vendin e tyre, ndërsa gjatësia e ditëve shënon jetën e amshuar."}]},{"title":"Kreu 3","blocks":[{"t":"p","x":"Veset lindin te ne kur i keqpërdorim fuqitë e shpirtit, domethënë fuqinë dëshiruese, fuqinë zemëruese dhe atë arsyetuese. Keqpërdorimi i fuqisë arsyetuese është padija dhe marrëzia, ndërsa ai i fuqisë zemëruese dhe i asaj dëshiruese është urrejtja dhe shthurja. Përdorimi i tyre i drejtë është njohja dhe urtësia, dashuria dhe dëlirësia. E në qoftë kështu, asgjë nga ato që Perëndia krijoi dhe solli në jetë nuk është e keqe."}]},{"title":"Kreu 4","blocks":[{"t":"p","x":"Nuk janë të këqija ushqimet, por grykësia, as lindja e fëmijëve, por kurvëria, as paratë, por argjenddashja, as lavdia, por lavdia e kotë. Prandaj ndër gjërat që janë nuk ka tjetër të keqe veç keqpërdorimit të tyre. Ai lind kur mendja lë pas dore punën që i takon sipas natyrës së vet."}]},{"title":"Kreu 5","blocks":[{"t":"p","x":"I lumuri Dionis thotë se e keqja te demonët është zemërimi pa arsye, dëshira pa mend dhe përfytyrimi i shfrenuar. Tek qeniet e arsyeshme, mungesa e arsyes, e mendjes dhe e përmbajtjes është privim nga arsyeja, nga mendja dhe nga gjykimi i matur. Por humbja e një cilësie vjen pasi e ke pasur atë. Pra, ka qenë një kohë kur edhe ata kishin arsye, mendje dhe gjykim plot druajtje. E në qoftë kështu, as demonët nuk janë të këqij për nga natyra. U bënë të këqij duke keqpërdorur fuqitë e tyre të natyrshme."}]},{"title":"Kreu 6","blocks":[{"t":"p","x":"Disa nga pasionet lindin shthurje, të tjera urrejtje, ndërsa të tjera lindin edhe shthurje, edhe urrejtje."}]},{"title":"Kreu 7","blocks":[{"t":"p","x":"Të ngrënët pa masë dhe lakmia për gjellë të shijshme lindin shthurjen. Argjenddashja dhe lavdia e kotë lindin urrejtjen ndaj të afërmit. Kurse dashuria e sëmurë për veten, nëna e tyre, i lind të dyja."}]},{"title":"Kreu 8","blocks":[{"t":"p","x":"Dashuria e sëmurë për veten është lidhja e pasionuar dhe e paarsyeshme pas trupit. Asaj i kundërvihen dashuria dhe vetëpërmbajtja. Kush e ka këtë lidhje, i ka të gjitha pasionet."}]},{"title":"Kreu 9","blocks":[{"t":"p","x":"«Askush», thotë Apostulli, «nuk e ka urryer mishin e vet». Por e rreh dhe e mban të nënshtruar, kuptohet, duke i dhënë vetëm ushqim e veshmbathje, dhe nga këto, vetëm aq sa i duhet për të jetuar. Kështu mund ta duash trupin pa pasion dhe, si shërbëtor të punëve hyjnore, ta ushqesh e ta mbash me kujdes, duke i dhënë vetëm ç’i mungon."}]},{"title":"Kreu 10","blocks":[{"t":"p","x":"Kujt i ka dashurinë njeriu, atij edhe nxiton t’i shërbejë. Nëse do Perëndinë, nxiton patjetër të bëjë çka i pëlqen Atij. Nëse do mishin, nxiton të përmbushë ato që e kënaqin atë."}]},{"title":"Kreu 11","blocks":[{"t":"p","x":"Perëndisë i pëlqejnë dashuria, dëlirësia, soditja dhe lutja. Mishit i pëlqejnë grykësia, shthurja dhe gjithçka që i ushqen ato. Prandaj «ata që janë në mish nuk mund t’i pëlqejnë Perëndisë», kurse «ata që janë të Krishtit e kryqëzuan mishin bashkë me pasionet dhe dëshirat e tij»."}]},{"title":"Kreu 12","blocks":[{"t":"p","x":"Kur mendja kthehet nga Perëndia, trupin e ka shërbëtor dhe nuk i jep më shumë nga sa i duhet për të jetuar. Kur kthehet nga mishi, bie vetë në robërinë e pasioneve, duke u kujdesur pareshtur për mishin, që t’ia plotësojë dëshirat."}]},{"title":"Kreu 13","blocks":[{"t":"p","x":"Nëse do t’i mposhtësh mendimet, përqendroje kujdesin te pasionet, dhe mendimet do t’i dëbosh lehtë. Kundër kurvërisë agjëro, rri zgjuar, mundohu, tërhiqu në vetmi. Kundër zemërimit dhe trishtimit shpërfill si lavdinë, ashtu edhe çnderimin e të mirat materiale. Kundër mërisë lutu për atë që të ka hidhëruar, dhe do të çlirohesh prej saj."}]},{"title":"Kreu 14","blocks":[{"t":"p","x":"Mos e mat veten me më të dobëtit ndër njerëz. Merre si masë urdhërimin e dashurisë. Kur matesh me ta, bie në gropën e mendjemadhësisë. Kur matesh me urdhërimin, ngjitesh në lartësinë e përulësisë."}]},{"title":"Kreu 15","blocks":[{"t":"p","x":"Nëse e ruan krejtësisht urdhërimin për të dashur të afërmin, përse ushqen brenda teje hidhërim kundër tij? A nuk është e qartë se, duke vënë gjërat kalimtare përpara dashurisë e duke u kapur pas tyre, i ke shpallur luftë vëllait tënd?"}]},{"title":"Kreu 16","blocks":[{"t":"p","x":"Njerëzit e lakmojnë arin më shumë për kënaqësitë që shumica mund të ndjekin me anë të tij, sesa për nevojën që kanë për të."}]},{"title":"Kreu 17","blocks":[{"t":"p","x":"Tri janë shkaqet e dashurisë për paranë, dashuria për kënaqësitë, lavdia e kotë dhe mungesa e besimit. Nga këto, mungesa e besimit është më e rëndë se dy të tjerat."}]},{"title":"Kreu 18","blocks":[{"t":"p","x":"Ai që do kënaqësitë e do paranë që të jetojë në salltanete. Ai që kërkon lavdi të kotë e do që të marrë lavdi prej saj. Ai që s’ka besim e do që ta fshehë e ta ruajë, nga frika e urisë, e pleqërisë, e sëmundjes a e mërgimit. Më shumë shpreson te paraja sesa te Perëndia, që krijoi gjithësinë dhe përkujdeset për të, deri edhe për gjallesën e fundit e më të vogël."}]},{"title":"Kreu 19","blocks":[{"t":"p","x":"Katër lloje njerëzish grumbullojnë para, tre që përmendëm dhe kujdestari i të mirave. Vetëm ky i fundit, kuptohet, grumbullon me të drejtë, që të mos reshtë kurrë së dhëni secilit sipas nevojës."}]},{"title":"Kreu 20","blocks":[{"t":"p","x":"Të gjitha mendimet e ngarkuara me pasion ose ndezin fuqinë dëshiruese të shpirtit, ose trazojnë fuqinë zemëruese, ose errësojnë fuqinë arsyetuese. Kështu mendjes i sëmuret syri me të cilin sodit gjërat shpirtërore dhe del përtej vetes në lutje. Prandaj murgu, veçanërisht ai që ushtron jetën e heshtjes, duhet t’u kushtojë mendimeve vëmendje të përpiktë, t’ua njohë rrënjët dhe t’ua presë. Ja si t’i njohë. Kujtimet për gratë, kur janë të mbarsura me pasion, i ndezin shpirtit fuqinë dëshiruese. Ato lindin nga teprimi në të ngrënë e në të pirë dhe nga takimet e shpeshta e të pamenduara me gratë. Uria, etja, vigjilja dhe tërheqja në vetmi ua presin hovin. Edhe zemërimin e trazojnë kujtimet plot pasion për ata që na kanë hidhëruar. Rrënjët e tyre janë dashuria për kënaqësitë, për lavdinë e kotë dhe për të mirat materiale. Njeriu i pushtuar nga pasioni hidhërohet për këto, qoftë se ia kanë marrë, qoftë se s’ka arritur t’i fitojë. Këto kujtime shuhen kur, për dashurinë e Perëndisë, i shpërfillim dhe i quajmë hiç të gjitha ato që i lindin."}]},{"title":"Kreu 21","blocks":[{"t":"p","x":"Perëndia njeh veten dhe njeh ato që ka krijuar. Edhe fuqitë e shenjta e njohin Perëndinë dhe i njohin ato që Perëndia ka krijuar. Por fuqitë e shenjta nuk e njohin Perëndinë dhe veprat e Tij në mënyrën si e njeh Perëndia veten dhe veprat e veta."}]},{"title":"Kreu 22","blocks":[{"t":"p","x":"Perëndia e njeh veten nga vetë qenësia e Tij e lumur. Ato që ka krijuar i njeh nga urtësia e Tij, me anën e së cilës dhe në të cilën i bëri të gjitha. Fuqitë e shenjta e njohin Perëndinë duke marrë pjesë tek Ai, ndonëse Ai është përtej çdo pjesëmarrjeje. Kurse ato që Ai ka krijuar i njohin duke rrokur atë që zbulohet në to përmes soditjes."}]},{"title":"Kreu 23","blocks":[{"t":"p","x":"Gjërat e krijuara janë jashtë mendjes, por mendja e përfton brenda vetes soditjen e tyre. Ndryshe qëndron puna me Perëndinë e përjetshëm, të pafund e të pakufishëm, që u fali qenieve të qenët, të qenët mirë dhe të qenët përgjithmonë."}]},{"title":"Kreu 24","blocks":[{"t":"p","x":"Qenia e arsyeshme dhe mendore merr pjesë te Perëndia i shenjtë me vetë faktin që është, me aftësinë për të qenë mirë, domethënë për mirësi e urtësi, dhe me hirin e të qenit përgjithmonë. Në këtë mënyrë e njeh Perëndinë. Kurse ato që Ai ka krijuar i njeh, siç thamë, duke përftuar në vete urtësinë mjeshtërore që soditet në krijesat. Kjo urtësi, kur përftohet në mendje, është një përfytyrim i zhveshur, pa ekzistencë më vete."}]},{"title":"Kreu 25","blocks":[{"t":"p","x":"Kur solli në të qenët natyrën e arsyeshme e mendore, Perëndia, prej mirësisë së vet të skajshme, e bëri pjesëtare të katër vetive hyjnore, që i mbajnë në qenësi, i mbrojnë dhe i ruajnë qeniet. Këto janë të qenët, të qenët përgjithmonë, mirësia dhe urtësia. Dy prej tyre ia dha vetë qenësisë së krijesës, kurse dy të tjerat aftësisë së saj për të zgjedhur lirisht. Qenësisë i dha të qenët dhe të qenët përgjithmonë, ndërsa zgjedhjes së lirë i besoi mirësinë dhe urtësinë, që krijesa të bëhet me pjesëmarrje ajo që Ai është për nga qenësia. Prandaj thuhet se u krijua sipas ikonës dhe sipas ngjashmërisë së Perëndisë. Sipas ikonës, sepse është, në shëmbëllimin e Atij që është, dhe është përgjithmonë, në shëmbëllimin e Atij që është përjetë, ndonëse krijesa ka fillim, por nuk ka mbarim. Sipas ngjashmërisë, sepse i miri i ngjan të Mirit dhe i urti të Urtit. Çka është Ai për nga natyra, bëhet krijesa me anë të hirit. Çdo natyrë e arsyeshme është sipas ikonës së Perëndisë. Sipas ngjashmërisë së Tij janë vetëm të mirët e të urtët."}]},{"title":"Kreu 26","blocks":[{"t":"p","x":"Mbarë qenësia e arsyeshme e mendore ndahet më dysh, në natyrën engjëllore dhe në atë njerëzore. Tërë natyra engjëllore ndahet nga ana e vet, sipas drejtimit të vullnetit, në dy bashkësi të mëdha, të shenjta e të përdhosura, domethënë në fuqitë e shenjta dhe në demonët e papastër. Edhe natyra njerëzore ndahet vetëm sipas dy drejtimeve të përgjithshme të vullnetit, në të përshpirtshëm e të paperëndishëm."}]},{"title":"Kreu 27","blocks":[{"t":"p","x":"Perëndia është vetë të qenët, vetë mirësia e vetë urtësia ose, për të folur më saktë, është përtej të gjitha këtyre. Prandaj, asgjë nuk i kundërvihet. Kurse krijesat kanë të kundërtat e tyre, se të gjitha e kanë qenien me pjesëmarrje dhe me hir, dhe ato që janë të arsyeshme e mendore kanë po ashtu aftësinë për mirësi e urtësi. Të qenët ka për të kundërt të mosqenët, kurse aftësia për mirësi e urtësi ka për të kundërt ligësinë e padijen. Të jenë gjithmonë apo të mos jenë, kjo qëndron në pushtetin e Krijuesit të tyre. Të marrin pjesë apo të mos marrin pjesë në mirësinë e Tij dhe në urtësinë e Tij, kjo qëndron në vullnetin e qenieve të arsyeshme."}]},{"title":"Kreu 28","blocks":[{"t":"p","x":"Helenët pohojnë se qenësia e gjërave ka bashkekzistuar përjetësisht me Perëndinë dhe se vetëm cilësitë e saj i ka marrë prej Tij. Prandaj thonë se qenësia nuk ka asgjë të kundërt dhe se kundërshtia ndodhet vetëm te cilësitë. Ne, përkundrazi, themi se vetëm qenësia hyjnore nuk ka gjë të kundërt, sepse është e përjetshme, e pafund dhe ua fal përjetësinë qenieve të tjera. Qenësia e gjërave ka për të kundërt të mosqenët. Në pushtetin e Atij që është në kuptimin e mirëfilltë qëndron nëse ajo do të jetë përherë apo nuk do të jetë. Por dhuratat e Tij janë të pakthyeshme. Prandaj ajo është gjithmonë dhe do të jetë, e mbajtur në jetë nga fuqia e Tij e gjithëpushtetshme, edhe pse, siç thamë, ka për të kundërt të mosqenët. Sepse Perëndia e solli nga mosqenia në qenie, dhe nga vullneti i Tij varet nëse ajo është apo nuk është."}]},{"title":"Kreu 29","blocks":[{"t":"p","x":"Sikurse e keqja është mungesë e së mirës dhe padija mungesë e njohjes, kështu edhe mosqenia është mungesë e të qenit. Kjo nuk i përket Atij që është në kuptimin e mirëfilltë, sepse Ai nuk ka të kundërt, por asaj që është duke marrë pjesë tek Ai që është me të vërtetë. Dy mungesat e para rrjedhin nga zgjedhja e krijesave. Mungesa e fundit varet nga vullneti i Krijuesit, i cili, prej mirësisë së Tij, do gjithmonë që qeniet të jenë dhe që gjithmonë të marrin të mira prej Tij."}]},{"title":"Kreu 30","blocks":[{"t":"p","x":"Ndër të gjitha gjërat e krijuara, disa janë qenie të arsyeshme e mendore, që mund të pranojnë të kundërtat, virtytin e vesin, njohjen e padijen. Të tjerat janë trupa të ndryshëm, të përbërë nga elemente të kundërta, domethënë nga dheu, ajri, zjarri dhe uji. Të parat janë krejt të patrup e jolëndore, ndonëse disa syresh janë të bashkuara me trupa. Të dytat përbëhen vetëm prej lëndës dhe formës."}]},{"title":"Kreu 31","blocks":[{"t":"p","x":"Të gjithë trupat, nga vetë natyra e tyre, janë të palëvizshëm. I vë në lëvizje shpirti, disa prej tyre një shpirt i arsyeshëm, disa një shpirt i paarsyeshëm dhe disa një shpirt pa ndjeshmëri."}]},{"title":"Kreu 32","blocks":[{"t":"p","x":"Ndër fuqitë e shpirtit, njëra ushqen dhe mundëson rritjen, tjetra përfytyron dhe shtyn në lëvizje, ndërsa një tjetër arsyeton dhe kupton. Bimët marrin pjesë vetëm në të parën. Gjallesat e paarsyeshme, përveç së parës, edhe në të dytën. Njerëzit, përveç të dyjave, edhe në të tretën. Dy fuqitë e para janë të prishshme. E treta dëshmohet si e paprishshme dhe e pavdekshme."}]},{"title":"Kreu 33","blocks":[{"t":"p","x":"Fuqitë e shenjta i japin dritë njëra-tjetrës dhe natyrës njerëzore i japin pjesë herë në virtytin e tyre, herë në njohjen që kanë. Nga virtyti i tyre i japin, për shembull, mirësinë që imiton Perëndinë, me anë të së cilës i bëjnë mirë vetes, njëra-tjetrës dhe qenieve që qëndrojnë më poshtë, duke i bërë të ngjashme me Perëndinë. Nga njohja e tyre i japin ose ndonjë kuptim më të lartë për Perëndinë, sepse «Ti je i Tejlarti përjetë, o Zot», ose ndonjë kuptim më të thellë për trupat, më të përpiktë për qeniet e patrup, më të kthjellët për përkujdesjen hyjnore, a më të qartë për gjykimin."}]},{"title":"Kreu 34","blocks":[{"t":"p","x":"Papastërtia e mendjes është, së pari, të kesh njohje të rreme. Së dyti, të mos njohësh diçka nga të vërtetat e përgjithshme. Këtu flas për mendjen njerëzore, sepse engjëllit i përket të njohë edhe çdo gjë të veçantë. Së treti, të mbash mendime të mbarsura me pasion. Së katërti, t’i japësh pëlqimin mëkatit."}]},{"title":"Kreu 35","blocks":[{"t":"p","x":"Papastërtia e shpirtit është të mos veprojë sipas natyrës së vet, sepse atëherë mendjes i lindin mendime të mbarsura me pasion. Shpirti vepron sipas natyrës kur fuqitë e tij që mund të preken nga pasionet, domethënë zemërimi dhe dëshira, mbeten të lira prej pasionit përballë gjërave dhe përfytyrimeve që ato ngjallin."}]},{"title":"Kreu 36","blocks":[{"t":"p","x":"Papastërtia e trupit është mëkati i kryer me vepër."}]},{"title":"Kreu 37","blocks":[{"t":"p","x":"Heshtjen e do ai që nuk është i lidhur me pasion pas gjërave të botës. Të gjithë njerëzit i do ai që nuk është i dhënë pas asgjëje njerëzore. Perëndinë dhe gjërat hyjnore i njeh ai që nuk skandalizohet me askënd, qoftë për fajet që tjetri ka bërë, qoftë për mendimet që atij vetë i lindin nga dyshimi."}]},{"title":"Kreu 38","blocks":[{"t":"p","x":"Është gjë e madhe të mos të të pushtojë pasioni përballë vetë gjërave. Por shumë më e madhe është të mbetesh i lirë nga pasioni edhe përballë përfytyrimeve të tyre."}]},{"title":"Kreu 39","blocks":[{"t":"p","x":"Dashuria dhe vetëpërmbajtja e ruajnë mendjen të lirë nga pasioni si përballë gjërave, ashtu edhe përballë përfytyrimeve të tyre."}]},{"title":"Kreu 40","blocks":[{"t":"p","x":"Mendja e atij që do Perëndinë nuk lufton kundër gjërave, as kundër përfytyrimeve të tyre, por kundër pasioneve që u janë ngjitur përfytyrimeve. Ajo nuk lufton, për shembull, kundër gruas ose kundër atij që e ka hidhëruar, as kundër shëmbëllimeve të tyre në kujtesë. Lufton kundër pasioneve që u janë ngjitur këtyre shëmbëllimeve."}]},{"title":"Kreu 41","blocks":[{"t":"p","x":"E gjithë lufta e murgut kundër demonëve synon të ndajë pasionet nga përfytyrimet. Përndryshe, ai nuk mund t’i shohë gjërat pa pasion."}]},{"title":"Kreu 42","blocks":[{"t":"p","x":"Tjetër është sendi, tjetër përfytyrimi i tij dhe tjetër pasioni. Send quajmë, për shembull, një burrë, një grua, arin dhe të ngjashmet me to. Përfytyrim quajmë kujtimin e thjeshtë të ndonjërit syresh. Pasion quajmë lidhjen e paarsyeshme apo urrejtjen e verbër ndaj ndonjërit prej tyre. Është pra kundër pasionit që lufton murgu."}]},{"title":"Kreu 43","blocks":[{"t":"p","x":"Një përfytyrim i mbarsur me pasion është një mendim i përbërë prej pasionit dhe përfytyrimit. Le ta ndajmë pasionin nga përfytyrimi dhe do të mbetet mendimi i thjeshtë. E bëjmë këtë ndarje, po të duam, me dashurinë shpirtërore dhe me vetëpërmbajtjen."}]},{"title":"Kreu 44","blocks":[{"t":"p","x":"Virtytet e shkëpusin mendjen nga pasionet. Soditjet shpirtërore e shkëpusin edhe nga përfytyrimet e thjeshta. Kurse lutja e pastër e sjell përpara vetë Perëndisë."}]},{"title":"Kreu 45","blocks":[{"t":"p","x":"Virtytet janë për hir të njohjes së krijesave, njohja për hir të atij që njeh, dhe ai që njeh për hir të Atij që njihet në mënyrë të panjohshme dhe që njeh përtej çdo njohjeje."}]},{"title":"Kreu 46","blocks":[{"t":"p","x":"Perëndia, që ka plotësi përtej çdo plotësie, nuk i solli krijesat në jetë ngaqë kishte nevojë për gjë. I krijoi që secila, sipas masës së vet, të marrë pjesë tek Ai e të gjejë ëmbëlsi tek Ai, dhe që Ai vetë të gëzohet për veprat e veta, kur t’i shohë tek gëzojnë e tek ngopen përherë, pa u ngopur kurrë, me Atë që s’ka të ngopur për to."}]},{"title":"Kreu 47","blocks":[{"t":"p","x":"Bota ka shumë të varfër në shpirt, por jo në kuptimin që duhet. Ka shumë që vajtojnë, por për humbje të pasurisë a për vdekje fëmijësh. Ka shumë të butë, por ndaj pasioneve të papastra. Ka shumë që kanë uri e etje, por për të rrëmbyer të mirat e tjetrit e për të fituar me padrejtësi. Ka shumë të mëshirshëm, por ndaj trupit të tyre dhe gjërave të trupit. Ka edhe zemërpastër, por për lavdi të kotë. Ka edhe paqebërës, por që bëjnë paqe duke ia nënshtruar shpirtin mishit. Ka shumë të përndjekur, por për sjelljen e tyre të shthurur. Ka shumë që i shajnë, por për mëkate të turpshme. Të lumur janë vetëm ata që i bëjnë dhe i pësojnë këto për hir të Krishtit dhe sipas Krishtit. Përse? Sepse «e tyre është mbretëria e qiejve» dhe «ata do të shohin Perëndinë», e ç’thuhet më tej. Nuk janë, pra, të lumur thjesht ngaqë i bëjnë dhe i pësojnë këto, se njësoj veprojnë edhe ata që përmendëm. Janë të lumur sepse i bëjnë dhe i pësojnë për hir të Krishtit dhe sipas Krishtit."}]},{"title":"Kreu 48","blocks":[{"t":"p","x":"Në çdo gjë që bëjmë, Perëndia sheh qëllimin, siç është thënë shpesh, nëse veprojmë për hir të Tij apo për diçka tjetër. Kur duam, pra, të bëjmë një të mirë, le të kemi për qëllim Perëndinë dhe jo t’u pëlqejmë njerëzve. Duke e mbajtur vështrimin gjithmonë tek Ai, le t’i bëjmë të gjitha për hir të Tij, që të mos na ndodhë edhe mundin ta heqim, edhe shpërblimin ta humbim."}]},{"title":"Kreu 49","blocks":[{"t":"p","x":"Në orën e lutjes hiqi nga mendja edhe përfytyrimet e thjeshta të gjërave njerëzore, edhe çfarë ke soditur në mbarë krijimin, që, tek përfytyron gjërat më të ulëta, të mos humbasësh Atë që është pakrahasueshëm më i lartë se gjithçka që është."}]},{"title":"Kreu 50","blocks":[{"t":"p","x":"Nëse e duam përnjëmend Perëndinë, nëpërmjet vetë kësaj dashurie i flakim pasionet. Ta duash Atë do të thotë të vësh Atë përpara botës dhe shpirtin përpara mishit. Do të thotë t’i shpërfillësh gjërat e botës dhe t’i kushtohesh Atij pareshtur, me vetëpërmbajtje, dashuri, lutje, psalmodi dhe me gjithçka që i pason këto."}]},{"title":"Kreu 51","blocks":[{"t":"p","x":"Nëse, duke iu kushtuar Perëndisë për një kohë të gjatë, përkujdesemi për pjesën e shpirtit që preket nga pasionet, sulmet e mendimeve nuk na nxjerrin më nga udha. Përkundrazi, duke i dalluar më përpikërisht shkaqet e tyre e duke ua prerë rrënjët, bëhemi më të mprehtë në gjykim. Kështu përmbushet te ne fjala: «Syri im i vështroi armiqtë e mi dhe veshi im do të dëgjojë për keqbërësit që ngrihen kundër meje»."}]},{"title":"Kreu 52","blocks":[{"t":"p","x":"Kur ta shohësh mendjen tënde që i trajton me shpresëtari e drejtësi përfytyrimet e gjërave të botës, dije se edhe trupi yt mbetet i pastër dhe pa mëkat. Por kur ta shohësh mendjen tënde se jepet pas mëkatit në mendime dhe ti nuk e ndal, dije se nuk do të vonojë të bjerë edhe trupi yt në po ato mëkate."}]},{"title":"Kreu 53","blocks":[{"t":"p","x":"Sikurse trupi ka për botë gjërat, edhe mendja ka për botë përfytyrimet. Dhe sikurse trupi kurvëron me trupin e një gruaje, edhe mendja kurvëron me përfytyrimin e gruas, duke përfytyruar trupin e vet, sepse në mendime sheh shëmbëllimin e trupit të vet tek bashkohet me shëmbëllimin e gruas. Po ashtu, me shëmbëllimin e trupit të vet, ajo hakmerret në mendime edhe kundër shëmbëllimit të atij që e ka hidhëruar. Kështu ndodh edhe me mëkatet e tjera. Ato që trupi bën me vepër në botën e gjërave, mendja i bën në botën e përfytyrimeve."}]},{"title":"Kreu 54","blocks":[{"t":"p","x":"Si të mos rrëqethesh, të mos shtangesh, të mos mbetesh pa mend? Perëndia dhe Ati «nuk gjykon askënd, por gjithë gjykimin ia ka dhënë Birit». Dhe Biri thërret: «Mos gjykoni, që të mos gjykoheni. Mos dënoni, që të mos dënoheni». Po kështu edhe Apostulli: «Mos gjykoni asgjë para kohe, derisa të vijë Zoti», dhe: «Me gjykimin me të cilin gjykon tjetrin, dënon veten tënde». Kurse njerëzit, në vend që të qajnë mëkatet e veta, ia kanë marrë gjykimin Birit dhe, si të ishin vetë të pamëkatë, gjykojnë e dënojnë njëri-tjetrin. Qielli u shtang nga kjo dhe toka u drodh, kurse ata, të pandjeshëm, as nuk turpërohen."}]},{"title":"Kreu 55","blocks":[{"t":"p","x":"Kush merret duke gjurmuar mëkatet e të tjerëve ose e gjykon vëllanë vetëm nga dyshimi, ende nuk ia ka nisur pendimit. As ka filluar t’i hetojë e t’i njohë mëkatet e veta, që në të vërtetë peshojnë më rëndë se shumë talanta plumbi, as e ka kuptuar ç’ia rëndon njeriut zemrën aq sa të dojë kotësinë e të kërkojë gënjeshtrën. Prandaj, si i pamend që ecën në errësirë, e heq mendjen nga mëkatet e veta e sjell ndër mend ato të të tjerëve, qofshin të vërteta, qofshin të sajuara prej dyshimit."}]},{"title":"Kreu 56","blocks":[{"t":"p","x":"Dashuria e sëmurë për veten, siç është thënë shpesh, është shkaku i të gjitha mendimeve të mbarsura me pasion. Prej saj lindin tre mendimet kryesore të dëshirës, ai i grykësisë, ai i argjenddashjes dhe ai i lavdisë së kotë. Nga grykësia lind mendimi i kurvërisë, nga argjenddashja ai i lakmisë për të pasur gjithnjë më shumë, nga lavdia e kotë ai i krenarisë. Gjithë të tjerët vijnë pas secilit prej këtyre të treve, mendimi i zemërimit, i trishtimit, i mërisë, i plogështisë shpirtërore, i smirës, i përgojimit e të tjerë si këta. Kështu pasionet e lidhin mendjen pas gjërave materiale dhe e mbajnë përtokë. I rëndojnë sipër si gur i stërmadh asaj që, për nga natyra, është më e lehtë dhe më e shpejtë se zjarri."}]},{"title":"Kreu 57","blocks":[{"t":"p","x":"Fillimi i të gjitha pasioneve është dashuria e sëmurë për veten, kurse fundi i tyre është krenaria. Dashuria e sëmurë për veten është lidhja e paarsyeshme pas trupit. Kush ia pret rrënjën asaj, ka prerë njëherësh të gjitha pasionet që lindin prej saj."}]},{"title":"Kreu 58","blocks":[{"t":"p","x":"Sikurse prindërit lidhen pas fëmijëve që u kanë lindur, edhe mendja lidhet natyrshëm pas fjalëve që ajo vetë nxjerr në jetë. Prindërve tepër të dhënë pas fëmijëve të vet, këta u duken më të mirët e më të bukurit ndër të gjithë, edhe sikur në çdo pikëpamje të jenë më qesharakët. Po kështu, një mendjeje të pamatur fjalët e veta i duken më të urtat ndër të gjitha, edhe sikur të jenë më të pavlerat. I urti nuk i sheh kështu fjalët e veta. Pikërisht kur i duket se është krejt i bindur për vërtetësinë dhe bukurinë e tyre, atëherë më shumë se kurrë ai nuk i zë besë gjykimit të vet. Ua lë të urtëve të tjerë t’ia gjykojnë fjalët, që «të mos vrapojë a të mos ketë vrapuar më kot», dhe prej tyre merr siguri."}]},{"title":"Kreu 59","blocks":[{"t":"p","x":"Kur e mposht ndonjërin prej pasioneve më të ulëta, si grykësinë, kurvërinë, zemërimin a lakminë, menjëherë të sulet mendimi i lavdisë së kotë. Po ta mposhtësh edhe atë, vendin ia zë mendimi i krenarisë."}]},{"title":"Kreu 60","blocks":[{"t":"p","x":"Kur e sundojnë shpirtin, të gjitha pasionet e ulëta e dëbojnë prej tij mendimin e lavdisë së kotë. Por, si të jenë mundur tërë pasionet që përmendëm, ato ia lëshojnë sërish udhën këtij mendimi që të kthehet te shpirti."}]},{"title":"Kreu 61","blocks":[{"t":"p","x":"Lavdia e kotë lind krenarinë edhe kur çrrënjoset, edhe kur mbetet. Kur çrrënjoset, të ngjall një mendim të lartë për veten. Kur mbetet, të bën mburravec."}]},{"title":"Kreu 62","blocks":[{"t":"p","x":"Vepra e bërë në fshehtësi e shuan lavdinë e kotë. Krenarinë e shuan ai që të mirat që ka arritur ia njeh Perëndisë."}]},{"title":"Kreu 63","blocks":[{"t":"p","x":"Kush është bërë i denjë ta njohë Perëndinë dhe e ka shijuar gjer në mbushulli ëmbëlsinë e kësaj njohjeje, i shpërfill të gjitha kënaqësitë që lindin prej fuqisë dëshiruese."}]},{"title":"Kreu 64","blocks":[{"t":"p","x":"Ai që dëshiron tokësoret dëshiron ose ushqime, ose çfarë i kënaq epshin, ose lavdi nga njerëzit, ose para, ose diçka tjetër që këto sjellin pas vetes. Nëse mendja nuk gjen diçka më të mirë se këto, drejt së cilës ta kthejë dëshirën, nuk do të bindet kurrë t’i shpërfillë krejtësisht. Por njohja e Perëndisë dhe e gjërave hyjnore është pakrahasueshëm më e lartë se të gjitha ato."}]},{"title":"Kreu 65","blocks":[{"t":"p","x":"Ata që i shpërfillin kënaqësitë e bëjnë këtë ose prej frikës, ose prej shpresës, ose prej njohjes dhe dashurisë për Perëndinë."}]},{"title":"Kreu 66","blocks":[{"t":"p","x":"Njohja e gjërave hyjnore, kur nuk ia prek zemrën njeriut, nuk e bind mendjen t’i shpërfillë krejtësisht gjërat materiale. Ajo i ngjan mendimit të thjeshtë të një sendi të ndjeshëm. Prandaj gjen shumë njerëz që kanë njohuri të shumta e megjithatë zhgërryhen në pasionet e mishit si derrat në llucë. Për pak kohë u pastruan me zell dhe arritën njohjen, por pastaj ranë në shkujdesje dhe i ngjanë Saulit, i cili u bë i denjë për mbretërinë, por jetoi në mënyrë të padenjë dhe u dëbua prej saj me zemërim të frikshëm."}]},{"title":"Kreu 67","blocks":[{"t":"p","x":"Sikurse mendimi i thjeshtë për gjërat njerëzore nuk e shtrëngon mendjen t’i shpërfillë gjërat hyjnore, po kështu as njohja e zhveshur e gjërave hyjnore nuk e bind t’i shpërfillë krejtësisht gjërat njerëzore. Sepse tani e vërteta na shfaqet në hije dhe në shëmbëllime. Prandaj na duhet ai pasion i lumur që është dashuria e shenjtë, e cila e lidh mendjen me ato që sodit në shpirt dhe e bind të parapëlqejë jolëndoret përpara lëndoreve dhe ato që rroken me mend e që janë hyjnore përpara atyre që rroken me shqisa."}]},{"title":"Kreu 68","blocks":[{"t":"p","x":"Kush i ka prerë pasionet dhe i ka kthyer mendimet në mendime të thjeshta, nuk i ka drejtuar medoemos që atëherë fuqitë e ndjenjës drejt gjërave hyjnore. Mund të mos ketë lidhje të pasionuar as me gjërat njerëzore, as me ato hyjnore. Kjo u ndodh atyre që merren ende vetëm me ushtrimin e virtytit dhe që nuk janë bërë ende të denjë për njohjen. Ata u rrinë larg pasioneve nga frika e dënimit ose nga shpresa e mbretërisë."}]},{"title":"Kreu 69","blocks":[{"t":"p","x":"«Ecim me anë të besimit, jo me anë të shikimit» dhe njohim si në pasqyrë e në enigmë. Prandaj duhet t’u kushtohemi gjatë këtyre gjërave, që, duke i përsiatur pareshtur e duke biseduar me to për shumë kohë, të fitojmë një prirje që vështirë të na shqitet nga ato që kemi soditur."}]},{"title":"Kreu 70","blocks":[{"t":"p","x":"Nëse ua presim për pak kohë shkaqet pasioneve dhe merremi me soditjet shpirtërore, por nuk qëndrojmë vazhdimisht në to duke i bërë punën tonë të përhershme, lehtë kthehemi prapë te pasionet e mishit. E vetmja e korrë që na mbetet është një njohje e zhveshur, e shoqëruar nga mendjemadhësia. Në fund, edhe vetë njohja na errësohet pak nga pak, dhe mendja kthehet e tëra pas gjërave materiale."}]},{"title":"Kreu 71","blocks":[{"t":"p","x":"Një dashuri e denjë për qortim e mban mendjen të zënë me gjërat materiale. Një dashuri e denjë për lëvdim e lidh atë me gjërat hyjnore. Sepse mendja, në ato gjëra ku qëndron gjatë, atje e ka zakon të zgjerohet. Dhe atje ku zgjerohet kthen edhe dëshirën, edhe dashurinë, qoftë te gjërat hyjnore e mendore që i përkasin natyrës së saj, qoftë te punët dhe pasionet e mishit."}]},{"title":"Kreu 72","blocks":[{"t":"p","x":"Perëndia krijoi botën e padukshme dhe atë të dukshme. Edhe shpirtin, edhe trupin Ai vetë i bëri. Nëse kaq e bukur është bota e dukshme, çfarë duhet të jetë vallë e padukshmja? Dhe nëse ajo është më e lartë se kjo, sa më lart qëndron nga të dyja Perëndia që i krijoi! Nëse Krijuesi i gjithçkaje të bukur është më i lartë se të gjitha krijesat, përse mendja lë Atë që qëndron mbi gjithçka dhe jepet pas gjërave më të ulëta nga të gjitha, domethënë pas pasioneve të mishit? A nuk është e qartë se me mishin ka bashkëjetuar dhe është mësuar që nga lindja, ndërsa për Atë që është më i lartë se të gjitha e përtej të gjithave ende nuk ka fituar përvojë të plotë? Nëse, me ushtrim të gjatë në përmbajtjen nga kënaqësitë dhe në përsiatjen e gjërave hyjnore, e shkëpusim mendjen pak nga pak nga kjo lidhje, ajo do të zgjerohet në gjërat hyjnore duke përparuar dalëngadalë, do ta njohë dinjitetin e saj dhe, më në fund, gjithë mallin e vet do ta kthejë nga Perëndia."}]},{"title":"Kreu 73","blocks":[{"t":"p","x":"Kush flet pa pasion për një mëkat të vëllait, e bën për njërin nga dy shkaqe, ose për ta ndrequr vetë vëllanë, ose për t’i bërë mirë një tjetri. Nëse e përmend për tjetër gjë, qoftë përpara tij, qoftë përpara të tjerëve, po flet për ta poshtëruar apo për ta përqeshur. Një njeri i tillë nuk do t’i shpëtojë braktisjes nga Perëndia. Do të bjerë patjetër në po atë faj ose në një tjetër dhe do të turpërohet kur ta qortojnë e ta përçmojnë të tjerët."}]},{"title":"Kreu 74","blocks":[{"t":"p","x":"Jo të gjithë ata që kryejnë të njëjtin mëkat e bëjnë për të njëjtën arsye. Tjetër është të mëkatosh nga zakoni dhe tjetër të merresh përpara në një çast dobësie. Ky i fundit as më përpara nuk e kishte mendjen te mëkati, as më pas nuk e mban aty, madje i dhemb thellë ajo që ndodhi. Me atë që mëkaton nga zakoni ndodh e kundërta. Edhe përpara veprës ai nuk pushonte së mëkatuari në mendime, edhe pasi e kreu mbetet me të njëjtën prirje."}]},{"title":"Kreu 75","blocks":[{"t":"p","x":"Kush u jepet virtyteve për lavdi të kotë, është e qartë se për lavdi të kotë i jepet edhe njohjes. Një njeri i tillë, kuptohet, as nuk vepron, as nuk flet që të tjerët të ndërtohen shpirtërisht. Në gjithçka kërkon të fitojë lavdinë e atyre që e shohin a që e dëgjojnë. Pasioni del në shesh kur ndonjëri nga këta ia qorton veprat ose fjalët dhe ai hidhërohet së tepërmi. Atij nuk i dhemb që të tjerët nuk ndërtuan shpirtin e tyre, se atë qëllim as nuk e kishte. I dhemb që atë vetë e përçmuan."}]},{"title":"Kreu 76","blocks":[{"t":"p","x":"Pasioni i argjenddashjes dallohet këtu, te gëzimi me të cilin merr njeriu dhe hidhërimi me të cilin ndan me të tjerët. Një i tillë nuk mund të jetë kujdestar i të mirave."}]},{"title":"Kreu 77","blocks":[{"t":"p","x":"Kur njeriu vuan, duron për njërën nga këto arsye: për dashurinë e Perëndisë, për shpresën e shpërblimit, nga frika e dënimit, nga frika e njerëzve, nga natyra e vet, për kënaqësi, për fitim, për lavdi të kotë ose nga nevoja."}]},{"title":"Kreu 78","blocks":[{"t":"p","x":"Tjetër është të çlirohesh nga mendimet dhe tjetër të jesh i lirë nga pasionet. Shpesh njeriu shpëton prej mendimeve për sa kohë që nuk i ka përpara ato gjëra pas të cilave lidhet me pasion. Por pasionet rrinë të fshehura në shpirt dhe, sapo shfaqen gjërat, ato dalin në shesh. Duhet, pra, ta vëzhgojmë mendjen kur është përballë gjërave dhe të dallojmë se ndaj cilës prej tyre ka pasion."}]},{"title":"Kreu 79","blocks":[{"t":"p","x":"Mik i vërtetë është ai që, në orën e sprovës, pa bujë e pa u trazuar, mban bashkë me të afërmin hidhërimet, nevojat dhe fatkeqësitë që i sollën rrethanat, sikur të ishin të vetat."}]},{"title":"Kreu 80","blocks":[{"t":"p","x":"Mos e shpërfill ndërgjegjen, që gjithnjë të këshillon për të mirën tënde. Ajo të mëson të gjykosh në mënyrë hyjnore e engjëllore, të çliron nga njollat e fshehta të zemrës dhe, në orën e largimit nga kjo botë, të fal guxim përpara Perëndisë."}]},{"title":"Kreu 81","blocks":[{"t":"p","x":"Nëse do të fitosh gjykim të kthjellët e masë dhe të mos jesh rob i mendjemadhësisë, kërko gjithmonë çfarë, ndër ato që janë, i mbetet e fshehtë njohjes sate. Kur të gjesh sa e sa gjëra nga më të ndryshmet që të kanë shpëtuar, do të habitesh për padijen tënde dhe do ta ulësh mendimin e lartë që ke për veten. Duke njohur veten, do të kuptosh shumë gjëra të mëdha e të mrekullueshme. Sepse të kujtosh se di, të pengon të përparosh në njohje."}]},{"title":"Kreu 82","blocks":[{"t":"p","x":"Vërtet dëshiron të shpëtojë ai që nuk u kundërvihet ilaçeve që e shërojnë. Ato janë dhembjet dhe hidhërimet që sjellin fatkeqësitë e ndryshme. Kush u kundërvihet nuk e di as se ç’punë po kryen këtu, as se ç’të mirë do të marrë me vete kur të largohet së këndejmi."}]},{"title":"Kreu 83","blocks":[{"t":"p","x":"Lavdia e kotë dhe argjenddashja lindin njëra-tjetrën. Ata që kërkojnë lavdinë e kotë grumbullojnë pasuri, dhe ata që kanë pasuri mbahen me të madh. Kështu ndodh me njerëzit e botës. Murgu, përkundrazi, ia ka ënda më fort lavdinë e kotë kur nuk zotëron asgjë. Po pati para, i fsheh, sepse ka turp që zotëron diçka që nuk i ka hije skimës së tij murgërore."}]},{"title":"Kreu 84","blocks":[{"t":"p","x":"Lavdia e kotë e murgut dallohet ngaqë ai mburret me virtytin dhe me gjithçka që e shoqëron atë. Krenaria e tij dallohet kur mbahet lart për ato që ka arritur, kur i përçmon të tjerët dhe ia njeh vetes ato arritje e jo Perëndisë. Lavdia e kotë dhe krenaria e njeriut të botës duken kur ai krenohet dhe mbahet lart për bukurinë, pasurinë, pushtetin dhe zgjuarsinë."}]},{"title":"Kreu 85","blocks":[{"t":"p","x":"Sukseset e njerëzve të botës janë rënie për murgjit dhe arritjet e murgjve janë rënie për njerëzit e botës. Për atë që jeton në botë arritje quhen pasuria, lavdia, pushteti, jeta plot kënaqësi, trupi i ushqyer mirë, gëzimi i fëmijëve të mbarë dhe çfarë i shoqëron këto. Po të jepet pas tyre, murgu humbet. Arritjet e murgut janë të mos zotërojë gjë, të jetojë pa lavdi e pa pushtet, të vetëpërmbahet, të durojë vuajtje dhe gjithçka që vjen pas tyre. Kur atij që do botën këto i vijnë pa i zgjedhur, i quan një rrënim të madh dhe shpesh rrezikon madje t’i vërë lakun vetes. Disa edhe e kanë bërë."}]},{"title":"Kreu 86","blocks":[{"t":"p","x":"Ushqimet u krijuan për dy qëllime, për të ushqyer dhe për të shëruar. Ata që i përdorin përtej këtyre dy qëllimeve i keqpërdorin dhuratat që Perëndia u dha për t’i përdorur dhe dënohen si njerëz të dhënë pas qejfeve. Kështu ndodh me çdo gjë: mëkati qëndron te keqpërdorimi."}]},{"title":"Kreu 87","blocks":[{"t":"p","x":"Përulësia është lutje e pandërprerë, me lot e mundime. Duke e thirrur gjithmonë Perëndinë në ndihmë, ajo nuk të lë të mbështetesh marrëzisht te forca a te mençuria jote dhe as të ngrihesh përmbi të tjerët. Këto janë sëmundje të rënda që i përkasin pasionit të krenarisë."}]},{"title":"Kreu 88","blocks":[{"t":"p","x":"Tjetër është të luftosh kundër një mendimi të thjeshtë që të mos zgjojë pasionin, dhe tjetër të luftosh kundër një mendimi tashmë të mbarsur me pasion, që të mos i japësh pëlqimin. Të dyja mënyrat e luftës nuk i lënë mendimet të zënë vend gjatë."}]},{"title":"Kreu 89","blocks":[{"t":"p","x":"Hidhërimi është i lidhur me mërinë. Pra, kur mendja sodit si në pasqyrë fytyrën e vëllait dhe e sheh me hidhërim, është e qartë se i mban mëri. «Udhët e atyre që mbajnë mëri shpien në vdekje», sepse «kushdo që mban mëri shkel ligjin»."}]},{"title":"Kreu 90","blocks":[{"t":"p","x":"Nëse ti i mban mëri dikujt, lutu për të, dhe do t’ia ndalësh hovin pasionit. Me anë të lutjes e ndan hidhërimin nga kujtimi i së keqes që të bëri. Dhe kur të bëhesh njeri plot dashuri e dhembshuri, do ta zhdukësh krejtësisht pasionin nga shpirti. Nëse dikush tjetër të mban mëri ty, bëhu zemërgjerë e i përulur ndaj tij, jeto në mirëkuptim me të, dhe do ta çlirosh nga pasioni i tij."}]},{"title":"Kreu 91","blocks":[{"t":"p","x":"Me shumë mund do ta fashitësh hidhërimin e atij që të ka zili. Sepse atë për të cilën të ka zili ai e quan fatkeqësi për veten, dhe s’ka mënyrë tjetër për t’ia fashitur hidhërimin, veçse t’ia fshehësh disi atë që i ngjall zili. Po nëse ajo u bën mirë shumë vetave, por atë e hidhëron, cilën palë do të lësh pas dore? Duhet, pra, t’i shërbesh së mirës së shumë vetave dhe, sa të kesh fuqi, të mos e lësh pas dore as atë. Mos lejo të të rrëmbejë ligësia e pasionit, sa të ngrihesh kundër atij që vuan e jo kundër pasionit. Përkundrazi, me përulësi çmoje atë si më të lartë se veten dhe jepi përparësi në çdo kohë, në çdo vend dhe në çdo gjë. Zilinë tënde, nga ana tjetër, mund ta ndalësh nëse gëzon bashkë me atë që ia ke zili për ato që e gëzojnë dhe hidhërohesh bashkë me të për ato që e hidhërojnë. Kështu përmbush fjalën e Apostullit: «Gëzohuni me ata që gëzohen dhe qani me ata që qajnë»."}]},{"title":"Kreu 92","blocks":[{"t":"p","x":"Mendja jonë qëndron ndërmjet dy qenieve, engjëllit dhe demonit. Secili vepron sipas asaj që i përket, njëri virtytin dhe tjetri ligësinë. Por mendja ka lirinë dhe fuqinë të ndjekë a t’i kundërvihet kujtdo prej tyre, sipas dëshirës së vet."}]},{"title":"Kreu 93","blocks":[{"t":"p","x":"Fuqitë e shenjta na nxitin drejt së mirës. Farat që kemi për nga natyra dhe zgjedhja jonë e mirë na vijnë në ndihmë. Kurse sulmeve të demonëve u japin fuqi pasionet dhe zgjedhja e keqe."}]},{"title":"Kreu 94","blocks":[{"t":"p","x":"Mendjen e pastër e mëson herë vetë Perëndia, kur vjen e prehet mbi të, herë fuqitë e shenjta që i sugjerojnë të mirën, herë natyra e gjërave kur mendja e sodit."}]},{"title":"Kreu 95","blocks":[{"t":"p","x":"Mendja që është bërë e denjë për njohjen duhet t’i ruajë pa pasion përfytyrimet e gjërave, të palëkundura ato që ka soditur dhe të kthjellët e pa asnjë re gjendjen e lutjes. Por nuk mund ta ruajë gjithmonë këtë gjendje, sepse, prej kurtheve të demonëve, mjegullohet nga avujt që ngrihen prej mishit."}]},{"title":"Kreu 96","blocks":[{"t":"p","x":"Jo për gjithçka që na hidhëron edhe zemërohemi, sepse më të shumta janë shkaqet e hidhërimit se ato të zemërimit. U thye ky send, humbi ai tjetri, vdiq filani. Për gjëra të tilla vetëm hidhërohemi. Për të tjera edhe hidhërohemi, edhe zemërohemi, kur na mungon gjykimi i urtë."}]},{"title":"Kreu 97","blocks":[{"t":"p","x":"Kur merr përfytyrimet e gjërave, mendja, sipas natyrës së vet, merr formën e secilit përfytyrim. Kur i sodit ato shpirtërisht, merr trajta të larmishme, sipas asaj që sodit çdo herë. Por kur arrin të jetë në Perëndinë, bëhet krejt pa trajtë dhe pa formë. Sepse, duke soditur Atë që është një e i pandarë, bëhet vetë një e pandarë dhe e tëra merr pamjen e dritës."}]},{"title":"Kreu 98","blocks":[{"t":"p","x":"I përsosur është shpirti që e ka kthyer krejtësisht nga Perëndia fuqinë e vet të ndjenjës."}]},{"title":"Kreu 99","blocks":[{"t":"p","x":"E përsosur është mendja që, nëpërmjet besimit të vërtetë, ka arritur të njohë përtej çdo njohjeje, në mënyrë krejt të panjohshme, Atë që tejkalon edhe vetë të panjohshmen. Ajo ka soditur të vërtetat e përgjithshme të krijesave të Tij dhe ka marrë prej Perëndisë një njohje që përfshin përkujdesjen dhe gjykimin e Tij në to. E them këtë sipas masës që u është dhënë njerëzve."}]},{"title":"Kreu 100","blocks":[{"t":"p","x":"Koha ndahet më tresh. Besimi shtrihet në të tria pjesët e saj, shpresa në njërën, dashuria në dy. Besimi dhe shpresa kanë një cak. Kurse dashuria mbetet në shekujt e pafund, e bashkuar përtej çdo bashkimi me Atë që është përtej çdo pafundësie, duke u rritur gjithmonë mbi çdo masë. Prandaj më e madhja e të gjithave është dashuria."}]}]},{"title":"Qindëshja e katërt","items":[{"title":"Kreu 1","blocks":[{"t":"p","x":"Së pari mendja mrekullohet kur sjell ndër mend pafundësinë e Perëndisë në çdo drejtim, atë det të pakalueshëm, për të cilin ka aq shumë mall. Pastaj shtanget kur mendon si i solli Ai qeniet nga asgjëja në të qenët. Por sikurse madhështia e Tij nuk ka kufi, ashtu as urtësisë së Tij nuk i gjendet fundi."}]},{"title":"Kreu 2","blocks":[{"t":"p","x":"Si të mos mrekullohet mendja kur sodit atë det të pamatë mirësie, që kapërcen çdo mrekullim? Si të mos mbetet e mahnitur kur mendon si dhe prej nga erdhën në jetë natyra e arsyeshme e mendore dhe të katër elementet prej të cilave përbëhen trupat, kur asnjë lëndë nuk ekzistonte para krijimit të tyre? Ç’është vallë ajo fuqi që, me të hyrë në veprim, i solli këto në të qenët? Por bijtë e helenëve nuk e pranojnë këtë, sepse nuk e njohin mirësinë e gjithëfuqishme, as urtësinë e njohjen e saj që veprojnë përtej çdo mendjeje."}]},{"title":"Kreu 3","blocks":[{"t":"p","x":"Perëndia, që është Krijues që nga amshimi, krijon kur do, me anë të Fjalës së Tij të njëqenëshme dhe të Shpirtit, prej mirësisë së Tij të pafund. Mos thuaj: «Përse krijoi vetëm tani, kur ka qenë gjithmonë i mirë?» Sepse edhe unë do të të them se urtësia e pahulumtueshme e qenësisë së pafund nuk bie nën njohjen njerëzore."}]},{"title":"Kreu 4","blocks":[{"t":"p","x":"Njohja e qenieve ishte në Krijuesin që nga amshimi. Kur deshi, Ai i dha asaj qenësi dhe e nxori në dritë. Është pa vend të dyshosh për Perëndinë e gjithëfuqishëm nëse mund t’i japë qenësi diçkaje kur Ai dëshiron."}]},{"title":"Kreu 5","blocks":[{"t":"p","x":"Kërko shkakun për të cilin krijoi Perëndia, sepse këtë mund ta njohësh. Por se si krijoi dhe përse krijoi vetëm së fundi, mos e kërko. Kjo njohje nuk është brenda fuqisë së mendjes sate. Ndër gjërat hyjnore, disa janë të kapshme për njeriun dhe disa janë të pakapshme. Soditja pa fre mund të të shtyjë në greminë, siç ka thënë një nga shenjtorët."}]},{"title":"Kreu 6","blocks":[{"t":"p","x":"Disa thonë se krijesat bashkekzistojnë me Perëndinë që nga amshimi, gjë që është e pamundur. Si mund të bashkekzistojë përjetësisht me Atë që është në çdo drejtim i pakufishëm ajo që është në çdo drejtim e kufizuar? Dhe si mund të quhen me të drejtë krijesa, nëse janë bashkë të amshuara me Krijuesin? Ky është arsyetimi i helenëve, të cilët e paraqesin Perëndinë vetëm si krijues të cilësive dhe aspak si krijues të qenësisë. Ne, që e kemi njohur Perëndinë si të gjithëfuqishëm, themi se Ai është krijues i vetë qenësive me gjithë cilësitë e tyre, e jo vetëm i cilësive. Kështu, pra, krijesat nuk bashkekzistojnë me Perëndinë që nga amshimi."}]},{"title":"Kreu 7","blocks":[{"t":"p","x":"Hyjnia dhe gjërat hyjnore në një vështrim janë të njohshme e në një tjetër të panjohshme. Hyjnia është e njohshme në ato që soditen rreth saj dhe e panjohshme në atë që është në vetvete."}]},{"title":"Kreu 8","blocks":[{"t":"p","x":"Mos kërko prirje të fituara a aftësi të mundshme në qenësinë e thjeshtë dhe të pafund të Trinisë së Shenjtë, se kështu do ta bëje të përbërë porsi krijesat. Për Perëndinë një mendim i tillë është edhe i paarsyeshëm, edhe i palejueshëm."}]},{"title":"Kreu 9","blocks":[{"t":"p","x":"Vetëm qenësia e pafund dhe e gjithëfuqishme, që krijoi gjithësinë, është e thjeshtë, e njëtrajtshme, e lirë prej cilësive përcaktuese, në paqe dhe pa kundërshti në vetvete. Kurse mbarë krijimi përbëhet nga qenësia dhe nga vetitë e rastësishme dhe gjithnjë ka nevojë për përkujdesjen hyjnore, sepse i nënshtrohet ndryshimit."}]},{"title":"Kreu 10","blocks":[{"t":"p","x":"Çdo qenie mendore dhe çdo qenie me shqisa, kur u sollën në jetë nga Perëndia, morën fuqitë me të cilat rrokin gjërat që janë. Qenia mendore i rrok nëpërmjet veprimeve të mendjes, kurse ajo shqisore me anë të shqisave."}]},{"title":"Kreu 11","blocks":[{"t":"p","x":"Te Perëndia vetëm merret pjesë. Kurse krijesa edhe merr pjesë, edhe u jep pjesë të tjerave. Ajo merr pjesë në të qenët dhe në të qenët mirë, por u jep të tjerave pjesë vetëm në të qenët mirë. Këtë në një mënyrë e bën natyra trupore dhe në një tjetër natyra e patrup."}]},{"title":"Kreu 12","blocks":[{"t":"p","x":"Natyra e patrup u jep të tjerave pjesë në të qenët mirë edhe kur flet, edhe kur vepron, edhe kur soditet. Natyra trupore vetëm kur soditet."}]},{"title":"Kreu 13","blocks":[{"t":"p","x":"Nëse qenia e arsyeshme dhe mendore do të jetë përherë apo nuk do të jetë, kjo varet nga vullneti i Atij që i krijoi të gjitha të mira. Por nëse krijesat do të jenë të mira apo të liga sipas zgjedhjes së tyre, kjo varet nga vullneti i vetë krijesave."}]},{"title":"Kreu 14","blocks":[{"t":"p","x":"E keqja nuk shihet në qenësinë e gjërave të krijuara, por në lëvizjen e tyre të gabuar e të paarsyeshme."}]},{"title":"Kreu 15","blocks":[{"t":"p","x":"Shpirti lëviz sipas arsyes kur vetëpërmbajtja i ka dhënë trajtë fuqisë së tij dëshiruese, kur fuqia e tij zemëruese kapet fort pas dashurisë duke i kthyer shpinën urrejtjes, dhe kur fuqia e tij arsyetuese qëndron pranë Perëndisë në lutje dhe në soditje shpirtërore."}]},{"title":"Kreu 16","blocks":[{"t":"p","x":"Ende nuk ka dashuri të përsosur dhe as nuk e njeh në thellësi përkujdesjen hyjnore ai që, kur vjen sprova, nuk i duron me zemër të gjerë hidhërimet që i bien, por shkëputet nga dashuria për vëllezërit e vet shpirtërorë."}]},{"title":"Kreu 17","blocks":[{"t":"p","x":"Qëllimi i përkujdesjes hyjnore është që, me anë të besimit të drejtë dhe të dashurisë shpirtërore, t’i bashkojë ata që ligësia i ka përçarë në gjithfarë mënyrash. Pikërisht për këtë pësoi Shpëtimtari, «që t’i mblidhte në një bijtë e shpërndarë të Perëndisë». Ai, pra, që nuk i duron bezditë, nuk i mban hidhërimet dhe nuk u qëndron mundimeve, ecën jashtë dashurisë hyjnore dhe jashtë qëllimit të përkujdesjes së saj."}]},{"title":"Kreu 18","blocks":[{"t":"p","x":"Në qoftë se «dashuria është zemërgjerë dhe plot mirësi», si mund të mos i largohet qëllimit të përkujdesjes hyjnore ai që ligështohet përballë hidhërimeve që i vijnë dhe prandaj sillet me ligësi ndaj atyre që e hidhëruan e shkëputet nga dashuria për ta?"}]},{"title":"Kreu 19","blocks":[{"t":"p","x":"Vështro mirë veten. Mos vallë ligësia që të ndan nga vëllai gjendet te ti e jo tek ai? Dhe nxito të pajtohesh me të, që të mos largohesh nga urdhërimi i dashurisë."}]},{"title":"Kreu 20","blocks":[{"t":"p","x":"Mos e shpërfill urdhërimin e dashurisë, sepse nëpërmjet tij do të jesh bir i Perëndisë. Po ta shkelësh, do të dalësh bir i gjehenës."}]},{"title":"Kreu 21","blocks":[{"t":"p","x":"Dashurinë ndërmjet miqve e këputin këto gjëra: ta kesh zili tjetrin ose të të ketë ai zili, ta dëmtosh ose të të dëmtojë, ta çnderosh ose të të çnderojë, dhe mendimet që lindin prej dyshimit. Shih mos ke bërë a ke pësuar diçka nga këto dhe prandaj je ndarë nga dashuria e mikut tënd."}]},{"title":"Kreu 22","blocks":[{"t":"p","x":"Të erdhi një sprovë nga vëllai dhe hidhërimi të shpuri në urrejtje. Mos u mund prej urrejtjes, por munde urrejtjen me dashuri. Do ta mundësh duke iu lutur Perëndisë me gjithë zemër për të, duke pranuar fjalën e tij të pajtimit apo duke ia ofruar vetë që ta zbutësh, duke e parë veten si shkaktar të sprovës dhe duke duruar me zemërgjerësi, derisa të kalojë reja."}]},{"title":"Kreu 23","blocks":[{"t":"p","x":"Zemërgjerë është ai që i pret fundin sprovës dhe shpreson në gëzimin e fitores që sjell qëndresa."}]},{"title":"Kreu 24","blocks":[{"t":"p","x":"«Njeriu zemërgjerë ka shumë urtësi», sepse gjithçka që i ndodh e vë në lidhje me përfundimin dhe, duke pritur atë, i duron hidhërimet. Dhe përfundimi, sipas Apostullit hyjnor, është jeta e amshuar. «Kjo është jeta e amshuar, të të njohin Ty, të vetmin Perëndi të vërtetë, dhe Jisu Krishtin, të cilin e dërgove»."}]},{"title":"Kreu 25","blocks":[{"t":"p","x":"Mos u trego i lehtë për ta flakur dashurinë shpirtërore, sepse njerëzve nuk u mbetet tjetër udhë shpëtimi."}]},{"title":"Kreu 26","blocks":[{"t":"p","x":"Atë që dje e kishe vëlla shpirtëror dhe e njihje si të virtytshëm, mos e gjyko sot si njeri të ulët e të lig për shkak të urrejtjes që i ligu ka zgjuar brenda teje. Me dashurinë që duron gjatë, sill ndër mend të mirat e djeshme dhe dëbo prej shpirtit urrejtjen e sotme."}]},{"title":"Kreu 27","blocks":[{"t":"p","x":"Atë që dje e lëvdoje si të mirë dhe i thurje lavde për virtytin, mos e përgojo sot si njeri të ulët e të lig. Meqë ti vetë kalove nga dashuria në urrejtje, mos i bëj qortimet për vëllanë përligjje të urrejtjes së ligë që ke brenda teje. Qëndro besnik ndaj të njëjtave fjalë lavdërimi, edhe nëse hidhërimi ende të mban të pushtuar, dhe do ta gjesh lehtë udhën e kthimit tek ajo dashuri që të shpëton."}]},{"title":"Kreu 28","blocks":[{"t":"p","x":"Kur takohesh me vëllezërit e tjerë, mos e përziej lavdërimin që zakonisht i bëje vëllait me ndonjë qortim të fshehur ndër fjalë, për shkak të hidhërimit që ruan ende ndaj tij. Në bisedë lavdëroje me një lavdërim të pastër dhe lutu për të me gjithë zemër si për veten tënde. Shumë shpejt do të çlirohesh nga urrejtja vdekjeprurëse."}]},{"title":"Kreu 29","blocks":[{"t":"p","x":"Mos thuaj «nuk e urrej vëllanë», kur kthen kryet edhe nga kujtimi i tij. Dëgjo ç’thotë Moisiu: «Mos e urre vëllanë tënd në zemrën tënde. Qortoje haptazi vëllanë tënd dhe nuk do të marrësh mbi vete mëkat për shkak të tij»."}]},{"title":"Kreu 30","blocks":[{"t":"p","x":"Edhe nëse vëllai, i shtyrë ndoshta nga tundimi, këmbëngul të flasë keq për ty, të paktën ti mos dil nga gjendja e dashurisë duke e lënë po atë demon të lig të të ngacmojë në mendime. Do të qëndrosh në dashuri nëse, kur të shajnë, bekon, kur të nxjerrin emër të keq, flet mirë, dhe kur të ngrenë kurthe, u do të mirën. Kjo është udha e urtësisë sipas Krishtit. Kush nuk e ecën këtë udhë, nuk banon bashkë me Të."}]},{"title":"Kreu 31","blocks":[{"t":"p","x":"Mos i merr për dashamirës ata që të sjellin fjalë që ngjallin në ty hidhërim e urrejtje kundër vëllait, edhe sikur të duket se thonë të vërtetën. Largohu prej tyre si prej gjarpërinjsh vdekjeprurës. Kështu edhe atyre ua pret udhën e përgojimit, edhe shpirtin tënd e çliron nga ligësia."}]},{"title":"Kreu 32","blocks":[{"t":"p","x":"Mos e shpo vëllanë me fjalë të tërthorta, që, kur ai të të përgjigjet po ashtu, të mos e dëbosh dashurinë nga zemrat e të dyve. Shko, foli hapur e me dashuri dhe qortoje. Kështu, duke zgjidhur shkakun e hidhërimit, do t’i çlirosh të dy nga trazimi dhe hidhërimi."}]},{"title":"Kreu 33","blocks":[{"t":"p","x":"Hetoje ndërgjegjen me gjithë përpikërinë, mos vallë është për fajin tënd që vëllai nuk është pajtuar me ty. Mos u mundo ta mashtrosh atë që t’i njeh të fshehtat, që do të të akuzojë në orën kur të largohesh nga kjo botë dhe që edhe në orën e lutjes të del përpara si pengesë."}]},{"title":"Kreu 34","blocks":[{"t":"p","x":"Në kohë paqeje mos i sill ndër mend fjalët që tha vëllai në kohën e hidhërimit, qofshin fjalë të rënda që t’i tha në sy, qofshin fjalë që ia tha një tjetri për ty dhe ti i dëgjove më pas. Po t’i japësh vend mendimit të mërisë, do të kthehesh te urrejtja vdekjeprurëse ndaj vëllait."}]},{"title":"Kreu 35","blocks":[{"t":"p","x":"Një shpirt i arsyeshëm që ushqen urrejtje për një njeri nuk mund të jetë në paqe me Perëndinë, dhënësin e urdhërimeve. Sepse Ai thotë: «Nëse nuk ua falni njerëzve fajet e tyre, as Ati juaj qiellor nuk do t’jua falë juve fajet tuaja». Nëse tjetri nuk do të pajtohet, të paktën ti ruaje veten nga urrejtja. Lutu për të me gjithë zemër dhe mos fol keq për të me askënd."}]},{"title":"Kreu 36","blocks":[{"t":"p","x":"Paqja e patregueshme e engjëjve të shenjtë mbahet nga këto dy dashuri, nga dashuria ndaj Perëndisë dhe nga dashuria për njëri-tjetrin. Kështu është edhe paqja e gjithë shenjtorëve që prej fillimit të kohëve. Sa bukur e ka thënë, pra, Shpëtimtari ynë se «prej këtyre dy urdhërimeve varet tërë Ligji dhe Profetët»!"}]},{"title":"Kreu 37","blocks":[{"t":"p","x":"Mos kërko t’i pëlqesh vetes dhe nuk do ta urresh vëllanë. Mos iu jep dashurisë së sëmurë për veten dhe do të duash Perëndinë."}]},{"title":"Kreu 38","blocks":[{"t":"p","x":"Kur të kesh zgjedhur të jetosh bashkë me vëllezër shpirtërorë, hiq dorë që te pragu nga dëshirat e tua. Në asnjë mënyrë tjetër nuk mund të jetosh në paqe as me Perëndinë, as me ata që banojnë me ty."}]},{"title":"Kreu 39","blocks":[{"t":"p","x":"Kush ka mundur të fitojë dashurinë e përsosur dhe gjithë jetën e vet e ka rregulluar sipas saj, ai «e quan Jisuin Zot në Shpirtin e Shenjtë». Dhe, kuptohet, për atë që bën të kundërtën vlen e kundërta."}]},{"title":"Kreu 40","blocks":[{"t":"p","x":"Dashurisë për Perëndinë i pëlqen gjithmonë t’i japë mendjes krahë që të hyjë në kuvendim me Të. Kurse dashuria për të afërmin e bën mendjen të mendojë gjithmonë mirë për të."}]},{"title":"Kreu 41","blocks":[{"t":"p","x":"Të mbash hidhërim ndaj njerëzve për gjëra kalimtare, t’u mbash mëri, t’i urresh ose të jesh rob i mendimeve të turpshme, janë tipare të atij që ende do lavdinë e kotë ose është i lidhur pas ndonjë gjëje materiale. Për shpirtin që do Perëndinë të gjitha këto janë krejt të huaja."}]},{"title":"Kreu 42","blocks":[{"t":"p","x":"Kur as me mendim të mos thuash a të mos bësh gjë të turpshme, kur të mos i mbash mëri atij që të dëmtoi a të përgojoi, dhe kur në orën e lutjes mendjen ta kesh përherë të lirë nga çdo gjë lëndore e nga çdo shëmbëllim, atëherë dije se ke arritur në masën e papasionshmërisë dhe të dashurisë së përsosur."}]},{"title":"Kreu 43","blocks":[{"t":"p","x":"Nuk është e vogël lufta për t’u çliruar nga lavdia e kotë. Njeriu çlirohet duke i ushtruar virtytet në fshehtësi dhe duke u lutur më shpesh. Shenja se është çliruar është kjo: nuk i mban më mëri as atij që e përgojoi, as atij që ende i flet keq."}]},{"title":"Kreu 44","blocks":[{"t":"p","x":"Nëse do të jesh i drejtë, jepi secilës pjesë të qenies sate atë që i takon. Kam fjalën për shpirtin dhe trupin. Fuqisë arsyetuese të shpirtit jepi lexime e soditje shpirtërore dhe lutje. Fuqisë zemëruese jepi dashurinë shpirtërore, që i kundërvihet urrejtjes. Fuqisë dëshiruese jepi dëlirësi e vetëpërmbajtje. Kurse trupit jepi për të ngrënë e për t’u veshur, vetëm çka i është krejt e domosdoshme."}]},{"title":"Kreu 45","blocks":[{"t":"p","x":"Mendja vepron sipas natyrës kur i ka pasionet të nënshtruara, kur sodit parimet e brendshme të qenieve dhe kur qëndron pranë Perëndisë."}]},{"title":"Kreu 46","blocks":[{"t":"p","x":"Ç’janë shëndeti dhe sëmundja për trupin e një gjallese, dhe drita e errësira për syrin, janë virtyti e vesi për shpirtin dhe njohja e padija për mendjen."}]},{"title":"Kreu 47","blocks":[{"t":"p","x":"I krishteri ushtron urtësinë në këto tri gjëra, në urdhërimet, në dogmat dhe në besimin. Urdhërimet e shkëpusin mendjen nga pasionet, dogmat e shpien drejt njohjes së qenieve, kurse besimi e shpie në soditjen e Trinisë së Shenjtë."}]},{"title":"Kreu 48","blocks":[{"t":"p","x":"Ndër ata që luftojnë, disa vetëm i zmbrapsin mendimet e ngarkuara me pasion, kurse disa u presin rrënjën edhe vetë pasioneve. Mendimet mund t’i zmbrapsësh, për shembull, me psalmodi a me lutje, duke e kthyer vëmendjen gjetiu ose duke u marrë me diçka tjetër atje ku ndodhesh. Por pasionet i pret kur shpërfill gjërat ndaj të cilave i ke ushqyer."}]},{"title":"Kreu 49","blocks":[{"t":"p","x":"Ndër gjërat pas të cilave lidhemi me pasion janë, për shembull, gruaja, paratë, lavdia e të tjera si këto. Murgu mund të bëhet i lirë nga lidhja me gruan kur, edhe pasi të jetë tërhequr nga bota, e ligështon trupin siç duhet me vetëpërmbajtje. Nga lidhja me paratë çlirohet kur e bind mendjen që në çdo gjë të kënaqet me atë që i mjafton. Nga lidhja me lavdinë çlirohet kur mëson ta dojë ushtrimin e virtyteve në fshehtësi, atje ku e sheh vetëm Perëndia. Kështu ndodh edhe me të tjerat. Dhe ai që i shpërfill këto, nuk arrin kurrë të urrejë njeri."}]},{"title":"Kreu 50","blocks":[{"t":"p","x":"Kush ka hequr dorë nga gjërat e jashtme, nga gruaja, pasuria e të ngjashme me to, ka bërë murg njeriun e jashtëm, por ende jo edhe të brendshmin. Kurse kush ka hequr dorë edhe nga përfytyrimet e tyre të mbarsura me pasion, ka bërë murg njeriun e brendshëm, domethënë mendjen. Njeriun e jashtëm mund ta bësh murg lehtë, mjaft të duash. Por të bësh murg njeriun e brendshëm nuk është luftë e vogël."}]},{"title":"Kreu 51","blocks":[{"t":"p","x":"Kush është vallë në këtë brez ai që është çliruar krejtësisht nga përfytyrimet e mbarsura me pasion dhe është bërë i denjë për lutjen e pastër e jolëndore? Kjo është shenja e murgut të brendshëm."}]},{"title":"Kreu 52","blocks":[{"t":"p","x":"Shumë pasione rrinë fshehur në shpirtrat tanë. Ato dalin në shesh kur shfaqen gjërat që i zgjojnë."}]},{"title":"Kreu 53","blocks":[{"t":"p","x":"Kur gjërat nuk janë të pranishme, njeriu mund të ketë arritur një farë papasionshmërie dhe pasionet të mos e mundojnë. Por le të shfaqen gjërat, dhe pasionet ia tërheqin sakaq mendjen andej-këtej."}]},{"title":"Kreu 54","blocks":[{"t":"p","x":"Mos pandeh se e ke arritur papasionshmërinë e përsosur për sa kohë që sendin nuk e ke përpara. Por kur ai të shfaqet dhe ti të mbetesh i patrazuar si përballë vetë sendit, ashtu edhe më pas përballë kujtimit të tij, atëherë dije se ke shkelur në truallin e papasionshmërisë. Por as atëherë mos u shkujdes. Virtyti i ushtruar gjatë i vdes pasionet, por po ta lësh pas dore, ato ngrihen përsëri."}]},{"title":"Kreu 55","blocks":[{"t":"p","x":"Kush e do Krishtin, patjetër edhe e imiton me sa fuqi ka. Krishti nuk pushoi së bëri mirë njerëzve. Kur ata e shpërblyen me mosmirënjohje dhe me blasfemi, Ai u tregua zemërgjerë. Kur e rrihnin dhe e vrisnin, Ai duroi, pa i vënë askujt në llogari as edhe një të keqe. Këto tri gjëra janë veprat e dashurisë ndaj të afërmit. Pa to, kush thotë se do Krishtin ose se do të fitojë mbretërinë e Tij, mashtron vetveten. Sepse Ai thotë: «Nuk do të hyjë në mbretërinë e qiejve kushdo që më thotë “Zot, Zot”, por ai që bën vullnetin e Atit tim». Dhe përsëri: «Ai që më do mua do t’i ruajë urdhërimet e mia», e ç’vijon më tej."}]},{"title":"Kreu 56","blocks":[{"t":"p","x":"Tërë qëllimi i urdhërimeve të Shpëtimtarit është ta çlirojnë mendjen nga mospërmbajtja e nga urrejtja dhe ta shpien në dashurinë për Atë vetë dhe për të afërmin. Prej këtyre të dyjave lind drita e njohjes së shenjtë që vepron në ne."}]},{"title":"Kreu 57","blocks":[{"t":"p","x":"Kur Perëndia të të ketë bërë të denjë të marrësh qoftë edhe një pjesë të njohjes, mos e lër pas dore dashurinë dhe vetëpërmbajtjen. Ato pastrojnë pjesën e shpirtit tënd që preket nga pasionet dhe gjithmonë ta bëjnë gati udhën për te njohja."}]},{"title":"Kreu 58","blocks":[{"t":"p","x":"Udha për te njohja është papasionshmëria dhe përulësia. Pa to askush nuk do ta shohë Zotin."}]},{"title":"Kreu 59","blocks":[{"t":"p","x":"Meqenëse «njohja të fryn, kurse dashuria ndërton», bashkoje me njohjen dashurinë dhe do të jesh i lirë nga mendjemadhësia. Do të bëhesh një ndërtues shpirtëror që ndërton edhe veten, edhe të gjithë ata që të afrohen."}]},{"title":"Kreu 60","blocks":[{"t":"p","x":"Ja si ndërton dashuria. Ajo nuk ka zili dhe nuk mbushet me vrer ndaj atyre që e kanë zili. Nuk e nxjerr në shesh për t’u dukur atë për të cilën të tjerët e kanë zili. Ai që ka dashuri nuk e quan veten se tashmë ia ka arritur qëllimit dhe, për ato që nuk i di, e pranon padijen pa u skuqur. Kështu dashuria e bën mendjen të lirë nga mendjemadhësia dhe e aftë të përparojë gjithmonë në njohje."}]},{"title":"Kreu 61","blocks":[{"t":"p","x":"Njohjen e shoqërojnë shpesh mendjemadhësia dhe zilia, sidomos në fillimet e saj. Mendjemadhësia vjen vetëm nga brenda. Zilia vjen edhe nga brenda, edhe nga jashtë: nga brenda kur ti ua ke zili atyre që kanë njohje, dhe nga jashtë kur zilia vjen prej atyre që kanë njohje. Dashuria i rrëzon të tria. Mendjemadhësinë, sepse «nuk krekoset». Zilinë që lind nga brenda, sepse «nuk ka zili». Zilinë që vjen nga jashtë, sepse «është zemërgjerë dhe plot mirësi». Prandaj atij që ka njohjen i duhet medoemos të fitojë edhe dashurinë, që ta ruajë mendjen të paplagosur në çdo gjë."}]},{"title":"Kreu 62","blocks":[{"t":"p","x":"Ai që është bërë i denjë për dhuratën e njohjes, por mban në zemër hidhërim, mëri a urrejtje ndaj një njeriu, i ngjan atij që i shpon sytë e vet me gjemba e me ferra. Ja përse njohja ka nevojë të domosdoshme për dashurinë."}]},{"title":"Kreu 63","blocks":[{"t":"p","x":"Mos ia kushto mishit tërë kujdesin tënd. Caktoji një ushtrim asketik aq sa ka fuqi dhe ktheje gjithë mendjen tënde nga jeta e brendshme. Sepse «ushtrimi trupor ka pak dobi, ndërsa shpresëtaria është e dobishme për të gjitha», e ç’vijon më tej."}]},{"title":"Kreu 64","blocks":[{"t":"p","x":"Kush rri pa ndërprerje në jetën e brendshme ruan dëlirësinë, duron me zemërgjerësi, bën mirë dhe përulet. Për më tepër, edhe sodit, edhe flet për Perëndinë, edhe lutet. Këtë ka parasysh Apostulli kur thotë: «Ecni sipas Shpirtit», e ç’vijon më tej."}]},{"title":"Kreu 65","blocks":[{"t":"p","x":"Kush nuk di të ecë në udhën shpirtërore nuk shqetësohet për përfytyrimet e mbarsura me pasion, por ia kushton tërë kujdesin mishit. Ose jepet pas grykësisë e shthurjes, hidhërohet, zemërohet, mban mëri dhe kështu errëson mendjen, ose ia kalon masës me ushtrimin asketik dhe mjegullon gjykimin."}]},{"title":"Kreu 66","blocks":[{"t":"p","x":"Shkrimi nuk hedh poshtë asgjë nga ato që Perëndia na dha për t’i përdorur. Ai dënon teprimin dhe ndreq përdorimin e paarsyeshëm. Për shembull, nuk na ndalon të hamë, të lindim fëmijë a të kemi pasuri e ta mbarështojmë drejt. Na ndalon grykësinë, kurvërinë e të tjera si këto. Madje as të mendojmë për këto gjëra nuk na ndalon, sepse ato u krijuan edhe për këtë. Na ndalon të mendojmë për to me pasion."}]},{"title":"Kreu 67","blocks":[{"t":"p","x":"Disa nga veprat që bëjmë sipas Perëndisë i bëjmë për të përmbushur një urdhërim. Të tjerat i bëjmë pa ndonjë urdhërim, por, si të thuash, si blatim vullnetar. Urdhërim është, për shembull, të duam Perëndinë dhe të afërmin, të duam armiqtë, të mos shkelim kurorën, të mos vrasim, e të tjera. Kur i shkelim këto, dënohemi. Kurse ruajtja e virgjërisë, jeta e pamartuar, të mos zotërosh asgjë, tërheqja në vetmi e sa vijojnë nuk janë urdhërime. Ato kanë vlerën e dhuratave, që, nëse prej dobësisë nuk arrijmë të përmbushim ndonjë urdhërim, me anë të këtyre dhuratave të kërkojmë hir te Zoti ynë i mirë."}]},{"title":"Kreu 68","blocks":[{"t":"p","x":"Kush e nderon jetën e pamartuar a virgjërinë, duhet medoemos t’i ketë ijët të ngjeshura dhe kandilin të ndezur. Ijët të ngjeshura me vetëpërmbajtje dhe kandilin të ndezur me lutje, me soditje dhe me dashuri shpirtërore."}]},{"title":"Kreu 69","blocks":[{"t":"p","x":"Disa nga vëllezërit kujtojnë se nuk kanë pjesë në dhuratat e Shpirtit të Shenjtë. Meqenëse e lënë pas dore zbatimin e urdhërimeve, nuk e dinë se ai që ka besim të pacenuar te Krishti i ka brenda vetes të gjitha së bashku dhuratat hyjnore. Për shkak të plogështisë sonë jemi larg dashurisë vepruese për Të, asaj dashurie që na i zbulon thesaret hyjnore brenda nesh. Prandaj është e kuptueshme që pandehim se nuk kemi pjesë në dhuratat hyjnore."}]},{"title":"Kreu 70","blocks":[{"t":"p","x":"Nëse «Krishti banon me anë të besimit në zemrat tona», sipas Apostullit hyjnor, dhe «në Të fshihen të gjitha thesaret e urtësisë e të njohjes», atëherë të gjitha thesaret e urtësisë e të njohjes janë fshehur në zemrat tona. Ato i zbulohen zemrës në atë masë që secili pastrohet duke zbatuar urdhërimet."}]},{"title":"Kreu 71","blocks":[{"t":"p","x":"Ky është thesari i fshehur në arën e zemrës sate, të cilin për shkak të plogështisë ende nuk e ke gjetur. Po ta kishe gjetur, do t’i kishe shitur të gjitha e do ta kishe blerë atë arë. Kurse tani arën e ke lënë pas dore dhe kujdesesh për ç’ka përqark saj, ku nuk gjen tjetër veç ferrave e gjembave."}]},{"title":"Kreu 72","blocks":[{"t":"p","x":"Prandaj Shpëtimtari thotë: «Lum ata që kanë zemrën të pastër, sepse ata do të shohin Perëndinë». Sepse Ai vetë është i fshehur në zemrën e atyre që besojnë tek Ai. Ata do ta shohin Atë dhe thesaret që janë në Të kur ta pastrojnë veten me dashuri e vetëpërmbajtje. Sa më thellë të pastrohen, aq më shumë do të shohin."}]},{"title":"Kreu 73","blocks":[{"t":"p","x":"Prandaj thotë përsëri: «Shitni gjërat që keni dhe jepni lëmoshë, dhe ja, gjithçka do të jetë e pastër për ju». Sepse atëherë nuk do të merren më me gjërat e trupit, por do të nxitojnë ta pastrojnë mendjen nga urrejtja e nga mospërmbajtja. Pikërisht mendjen Zoti e quan zemër. Sepse këto pasione e ndotin mendjen dhe nuk e lënë të shohë Zotin që banon në të me anë të hirit të Pagëzimit të shenjtë."}]},{"title":"Kreu 74","blocks":[{"t":"p","x":"Shkrimi i quan virtytet «udhë». Por më e madhja e të gjitha virtyteve është dashuria. Prandaj Apostulli thoshte: «Po ju tregoj edhe një udhë që ua kalon të gjithave», sepse dashuria na bind t’i shpërfillim gjërat materiale e të mos vëmë asgjë të përkohshme përpara gjërave të amshuara."}]},{"title":"Kreu 75","blocks":[{"t":"p","x":"Dashuria për Perëndinë i kundërvihet dëshirës, sepse e bind mendjen të përmbahet nga kënaqësitë. Dashuria për të afërmin i kundërvihet zemërimit, sepse na bën t’i shpërfillim lavdinë e pasurinë. Këta janë dy dinarët që Shpëtimtari i dha hanxhiut që të kujdesej për ty. Mos u trego mosmirënjohës duke u bërë shok me kusarët, se mos të plagosin përsëri dhe këtë herë të të gjejnë jo më gjysmë të vdekur, por të vdekur."}]},{"title":"Kreu 76","blocks":[{"t":"p","x":"Pastroje mendjen tënde nga zemërimi, nga mëria dhe nga mendimet e turpshme, dhe atëherë do të mund të njohësh si banon Krishti brenda teje."}]},{"title":"Kreu 77","blocks":[{"t":"p","x":"Kush të ndriçoi që të besosh në Trininë e shenjtë, të adhurueshme dhe të njëqenëshme? Kush të bëri të njohësh ekonominë e mishërimit të Njërit prej Trinisë së Shenjtë? Kush të mësoi të vërtetat për qeniet e patrup, për krijimin dhe mbarimin e botës së dukshme, për ngjalljen së vdekurish dhe jetën e amshuar, për lavdinë e mbretërisë së qiejve dhe gjykimin e frikshëm? A nuk ishte hiri i Krishtit që banon në ty, pengu i Shpirtit të Shenjtë? Ç’ka më të madhe se ky hir, ç’ka më të çmuar se kjo urtësi e kjo njohje, ç’ka më të lartë se këto premtime? Nëse, për shkak se jemi të plogësht e të shkujdesur, nuk pastrohemi nga pasionet që na ndotin dhe na verbojnë mendjen, që të mund t’i shohim këto të vërteta më qartë se diellin, le t’ia vëmë fajin vetes dhe të mos mohojmë se hiri banon brenda nesh."}]},{"title":"Kreu 78","blocks":[{"t":"p","x":"Perëndia, që të premtoi të mirat e amshuara dhe që ta ka dhënë në zemër pengun e Shpirtit, të urdhëroi të përkujdesesh për jetën tënde, që njeriu i brendshëm, i çliruar nga pasionet, të fillojë që këtu t’i shijojë ato të mira."}]},{"title":"Kreu 79","blocks":[{"t":"p","x":"Kur të jesh bërë i denjë për soditjet e larta e hyjnore, kujdesu fort për dashurinë dhe vetëpërmbajtjen, që, duke e ruajtur të patrazuar pjesën e shpirtit që preket nga pasionet, drita e shpirtit tënd të mos të shuhet."}]},{"title":"Kreu 80","blocks":[{"t":"p","x":"Vëri fre me dashuri fuqisë zemëruese të shpirtit, zbute me vetëpërmbajtje zjarrin e fuqisë së tij dëshiruese dhe jepi krahë me lutje fuqisë së tij arsyetuese. Atëherë drita e mendjes nuk do të venitet kurrë."}]},{"title":"Kreu 81","blocks":[{"t":"p","x":"Ndër gjërat që këputin dashurinë janë çnderimi, dëmi, shpifja kundër besimit a jetës së njeriut, të rrahurat, plagët e të tjera si këto, qofshin të pësuara prej atij vetë, qofshin prej njerëzve të tij, të afërm a miq. Kush e këput dashurinë për shkak të ndonjërës prej këtyre, ende nuk e ka njohur qëllimin e urdhërimeve të Krishtit."}]},{"title":"Kreu 82","blocks":[{"t":"p","x":"Përpiqu me gjithë fuqinë tënde ta duash çdo njeri. E nëse këtë ende nuk e arrin dot, të paktën mos urre askënd. Por edhe këtë nuk do të mund ta bësh nëse nuk i shpërfill gjërat e botës."}]},{"title":"Kreu 83","blocks":[{"t":"p","x":"Dikush blasfemoi. Mos urre atë. Urre blasfeminë dhe demonin që e shtyu të blasfemojë. Sepse po të urresh atë që blasfemoi, ke urryer një njeri dhe ke shkelur urdhërimin. Atë që ai bëri me fjalë, ti po e bën me vepër. Por nëse e ruan urdhërimin, dëshmoje me veprat e dashurisë dhe, po të kesh ndonjë fuqi, ndihmoje të çlirohet nga e keqja."}]},{"title":"Kreu 84","blocks":[{"t":"p","x":"Krishti nuk do që ti të ushqesh ndaj ndonjë njeriu as urrejtje, as hidhërim, as zemërim, as mëri, në asnjë mënyrë dhe për asnjë gjë kalimtare. Këtë e shpallin me zë të lartë, nga kreu në fund, të katër Ungjijtë."}]},{"title":"Kreu 85","blocks":[{"t":"p","x":"Jemi shumë ata që flasim dhe pak ata që veprojmë. Por askush nuk duhet ta shtrembërojë fjalën e Perëndisë për shkak të shkujdesjes së vet. Le ta pohojë dobësinë e tij e të mos e fshehë të vërtetën e Perëndisë, që, bashkë me shkeljen e urdhërimeve, të mos mbajmë faj edhe për shtrembërimin e kuptimit të asaj që thotë Perëndia."}]},{"title":"Kreu 86","blocks":[{"t":"p","x":"Dashuria dhe vetëpërmbajtja e çlirojnë shpirtin nga pasionet. Leximi dhe soditja e çlirojnë mendjen nga padija. Kurse gjendja e lutjes e sjell mendjen përpara vetë Perëndisë."}]},{"title":"Kreu 87","blocks":[{"t":"p","x":"Kur demonët shohin se i shpërfillim gjërat e botës që të mos urrejmë njerëzit për shkak të tyre e të biem nga dashuria, atëherë ngrenë shpifje kundër nesh. Kërkojnë që ne, duke mos e duruar dot hidhërimin, të urrejmë ata që na shpifën."}]},{"title":"Kreu 88","blocks":[{"t":"p","x":"Nuk ka dhembje më të rëndë për shpirtin se shpifja, qoftë kur të shpifin për besimin, qoftë për jetën tënde. Askush nuk mund të ngrihet mbi të, përveç atij që, si Susana, e mban vështrimin nga Perëndia. Vetëm Ai mund ta shpëtojë nga ngushtica, siç e shpëtoi edhe atë, t’i bindë njerëzit për të vërtetën, siç bëri edhe për të, dhe ta ngushëllojë shpirtin me shpresë."}]},{"title":"Kreu 89","blocks":[{"t":"p","x":"Sa më shumë të lutesh nga shpirti për atë që të ka shpifur, aq më shumë Perëndia do t’i bindë për të vërtetën ata që kanë marrë shkandull."}]},{"title":"Kreu 90","blocks":[{"t":"p","x":"I mirë nga natyra është vetëm Perëndia. I mirë nga zgjedhja është vetëm ai që e imiton Perëndinë. Sepse ai ka për qëllim t’i bashkojë njerëzit e ligj me Atë që është i mirë nga natyra, që edhe ata të bëhen të mirë. Prandaj, kur ata e shajnë, ai bekon. Kur e përndjekin, ai duron. Kur e përgojojnë, ai u flet me ëmbëlsi. Kur e vrasin, ai lutet për ta. I bën të gjitha që të mos largohet nga qëllimi i dashurisë, dhe kjo dashuri është vetë Perëndia ynë."}]},{"title":"Kreu 91","blocks":[{"t":"p","x":"Urdhërimet e Zotit na mësojnë t’i përdorim me urtësi ato gjëra që në vetvete nuk janë as të mira, as të këqija. Përdorimi i tyre i urtë pastron gjendjen e shpirtit. Gjendja e pastër lind aftësinë për të dalluar. Kjo aftësi lind papasionshmërinë dhe prej saj lind dashuria e përsosur."}]},{"title":"Kreu 92","blocks":[{"t":"p","x":"Ende nuk ka arritur papasionshmërinë ai që, kur i vjen një sprovë, nuk mund t’ia kalojë mikut një të metë, qoftë e vërtetë, qoftë vetëm e dukshme. Sepse pasionet që rrinë brenda shpirtit, kur trazohen, e verbojnë gjykimin dhe nuk e lënë as të shohë qartë rrezet e së vërtetës, as të dallojë më të mirën nga më e keqja. Një njeri i tillë, pra, nuk ka fituar ende as dashurinë e përsosur, atë që e nxjerr jashtë frikën e gjykimit."}]},{"title":"Kreu 93","blocks":[{"t":"p","x":"«Asgjë nuk mund të vihet në këmbim të një miku besnik», sepse fatkeqësitë e mikut ai i quan të vetat dhe i mban bashkë me të, i gatshëm të vuajë deri në vdekje."}]},{"title":"Kreu 94","blocks":[{"t":"p","x":"Miqtë janë të shumtë, por në ditë të mbarë. Në ditën e sprovës mezi gjen qoftë edhe një."}]},{"title":"Kreu 95","blocks":[{"t":"p","x":"Çdo njeri duhet ta duam me gjithë shpirt. Por shpresën duhet ta vëmë vetëm te Perëndia dhe Atij t’i shërbejmë me gjithë fuqinë tonë. Sepse, për sa kohë Ai na mbron, të gjithë miqtë kujdesen për ne dhe të gjithë armiqtë janë të pafuqishëm përballë nesh. Kurse, nëse Ai na braktis, të gjithë miqtë na kthejnë shpinën dhe të gjithë armiqtë marrin fuqi kundër nesh."}]},{"title":"Kreu 96","blocks":[{"t":"p","x":"Ka katër mënyra kryesore të braktisjes. E para i përket ekonomisë së shpëtimit, si në rastin e Zotit: përmes braktisjes së Tij në dukje, të braktisurit të shpëtojnë. E dyta shërben për të vënë në provë, si në rastin e Jovit dhe të Josifit, që njëri të shfaqej si shtyllë e trimërisë e tjetri si shtyllë e dëlirësisë. E treta shërben për edukimin atëror, si në rastin e Apostullit, që nëpërmjet përulësisë ta ruante hirin e pamasë. E katërta është kur Perëndia e kthen fytyrën mënjanë, si në rastin e judenjve, që nëpërmjet ndëshkimit të zbuteshin e të ktheheshin në pendim. Por të gjitha këto mënyra janë shpëtimtare dhe plot e përplot me mirësinë e urtësinë hyjnore."}]},{"title":"Kreu 97","blocks":[{"t":"p","x":"Vetëm ata që i ruajnë me përpikëri urdhërimet dhe që vërtet janë futur në misterin e gjykimeve hyjnore nuk i braktisin miqtë kur ata, me lejimin e Perëndisë, vihen në provë. Kurse ata që i shpërfillin urdhërimet dhe nuk e njohin misterin e gjykimeve hyjnore, kur mikut i ecën mbarë gëzojnë të mirat bashkë me të. Por kur e zë sprova e vuan, e braktisin. Nganjëherë madje marrin anën e kundërshtarëve të tij."}]},{"title":"Kreu 98","blocks":[{"t":"p","x":"Miqtë e Krishtit i duan të gjithë me të vërtetë, por jo të gjithë ua kthejnë dashurinë. Miqtë e botës nuk i duan të gjithë dhe as nuk duhen nga të gjithë. Miqtë e Krishtit e ruajnë të pandërprerë dashurinë e tyre deri në fund. Miqtë e botës e ruajnë vetëm derisa të përplasen me njëri-tjetrin për gjërat e botës."}]},{"title":"Kreu 99","blocks":[{"t":"p","x":"«Miku besnik është një strehë e fortë», sepse, kur mikut i ecën mbarë, ai është këshilltar i mirë dhe bashkëpunëtor që ka një shpirt me të. Kur miku vuan, ai është ndihmësi më besnik dhe mbrojtësi më i dhembshur."}]},{"title":"Kreu 100","blocks":[{"t":"p","x":"Shumë veta kanë thënë shumë gjëra për dashurinë. Por, po ta kërkosh, vetëm te nxënësit e Krishtit do ta gjesh, sepse vetëm ata patën mësues të dashurisë vetë Dashurinë e vërtetë. Për të thoshin: «Edhe sikur të kem dhuntinë e profecisë dhe të njoh të gjitha misteret e gjithë njohjen, po të mos kem dashuri, asgjë nuk më bën dobi». Kush, pra, ka fituar dashurinë, ka fituar vetë Perëndinë, sepse Perëndia është dashuri."},{"t":"p","x":"Atij i qoftë lavdia në jetë të jetëve. Amin."}]}]},{"title":"Burimi i botimit","items":[{"title":"Burimi i tekstit greqisht","blocks":[{"t":"p","x":"Burimi i tekstit greqisht. Universiteti i Egjeut, «Δρόμοι της Πίστης – Ψηφιακή Πατρολογία», 2006. PG_91AGI.pdf, f. 24–61. Për këtë vepër, botuesit morën për bazë tekstin e Thesaurus Linguae Graecae dhe e krahasuan me botimin «Γρηγόριος ο Παλαμάς», vëll. 14, To Vyzantion, Selanik, 1992."}]}]}]};
